    val list: List<BProb> = ArrayList<BProb>().also { l -> p0(l); p1(l); p2(l); p3(l); p4(l); p5(l); p6(l); p7(l); p8(l); p9(l); p10(l); p11(l) }
    private fun p0(l: MutableList<BProb>) {
        l.add(BProb(id = "e23_01", topic = "arit", level = 2, text = "Samuel un estudiante de la Facultad de Ciencias Matemáticas de la UNMSM, en uno de sus días de descanso se pone a contar las hojas de un libro de una manera bastante particular, él se da cuenta que, al agrupar de 12 en 12, de 18 en 18 y de 20 en 20, siempre le sobran 7 hojas. Si el libro tiene entre 500 y 1200 páginas, ¿cuántas hojas tiene como máximo dicho libro?", opts = listOf("277", "367", "547", "727"), vals = listOf("277", "367", "547", "727"), correct = 2, check = "max(select(h->h>=250 and h<=600,seq(180*k+7,k,0,10)))", steps = listOf("Llamamos N al número de hojas. Como al agrupar de 12, de 18 y de 20 siempre sobran 7, el número N − 7 es múltiplo de 12, de 18 y de 20 a la vez.", "Calculamos el MCM: 12 = 2²·3, 18 = 2·3² y 20 = 2²·5. Se toma cada primo con su mayor exponente: 2²·3²·5 = 180.", "Entonces N = 180k + 7. Los valores posibles son 7, 187, 367, 547, 727, 907, …", "Pasamos el rango a hojas: entre 500 y 1200 páginas equivale a entre 250 y 600 hojas, porque cada hoja tiene 2 páginas.", "De la lista solo 367 y 547 están entre 250 y 600. Nos piden el máximo: 547 hojas."), theory = "Si un número deja el mismo residuo al dividirlo entre varios divisores, entonces es un múltiplo común de esos divisores más el residuo. El menor múltiplo común es el MCM.", idea = "El enunciado cuenta hojas, pero da el rango en páginas. Cada hoja tiene dos páginas.", mistake = "Usar el rango de 500 a 1200 como si fueran hojas. Así el mayor valor entre las opciones sería 727, que es la alternativa D.", verify = "547 − 7 = 540 y 540 se divide exacto entre 12, 18 y 20. Además 547 hojas son 1094 páginas, que está entre 500 y 1200. El siguiente candidato, 727, serían 1454 páginas y se pasa.", trap = "max(select(h->irem(h-7,180)==0 and h>=500 and h<=1200,[277,367,547,727]))", src = "oficial", year = 2023, num = 1, trapOpt = 3, official = 2))
        l.add(BProb(id = "e23_02", topic = "arit", level = 2, text = "Dos señales luminosas se apagaron juntas en un determinado instante. Si se sabe que una de ellas permanece 10 segundos apagada y 34 segundos encendida, mientras que la otra permanece 10 segundos apagada y 45 segundos encendida, ¿después de cuántos segundos ambas señales se apagan juntas nuevamente por segunda vez?", opts = listOf("180", "220", "240", "210"), vals = listOf("180", "220", "240", "210"), correct = 1, check = "lcm(10+34,10+45)", steps = listOf("La primera señal repite su ciclo cada 10 + 34 = 44 segundos. Se apaga en los instantes 0, 44, 88, 132, 176, 220, …", "La segunda repite su ciclo cada 10 + 45 = 55 segundos. Se apaga en 0, 55, 110, 165, 220, …", "Se apagan juntas cuando el tiempo es múltiplo de 44 y de 55 a la vez. Como 44 = 2²·11 y 55 = 5·11, el MCM es 2²·5·11 = 220.", "La primera vez que se apagaron juntas fue el instante inicial. La segunda vez es a los 220 segundos."), theory = "Cuando dos fenómenos se repiten con periodos distintos y coinciden en un instante, vuelven a coincidir cada MCM de sus periodos.", idea = "El periodo de cada señal es el ciclo completo, apagada más encendida, no solo el tiempo encendida.", mistake = "Tomar solo los tiempos encendidos, 34 y 45, cuyo MCM es 1530, o contar dos coincidencias después del inicio y obtener 440. Ninguno de esos valores está entre las opciones.", verify = "220 ÷ 44 = 5 y 220 ÷ 55 = 4, ambas exactas. En las dos listas no hay ningún número común entre 0 y 220.", src = "oficial", year = 2023, num = 2, official = 1))
        l.add(BProb(id = "e23_03", topic = "arit", level = 2, text = "Tres rollos de alambre de acero de igual grosor y cuyas longitudes en metros son 720, 280 y 216; se quieren dividir, sin desperdiciar material, en trozos todos de igual longitud. ¿Cuántos trozos de alambre se obtendrán como mínimo?", opts = listOf("304", "142", "152", "167"), vals = listOf("304", "142", "152", "167"), correct = 2, check = "720/gcd(gcd(720,280),216)+280/gcd(gcd(720,280),216)+216/gcd(gcd(720,280),216)", steps = listOf("La longitud de cada trozo debe dividir exactamente a 720, a 280 y a 216.", "Calculamos el MCD: 720 = 2⁴·3²·5, 280 = 2³·5·7 y 216 = 2³·3³. El único factor común a los tres es 2³, así que el MCD es 8 m.", "Contamos los trozos de 8 m: 720 ÷ 8 = 90, 280 ÷ 8 = 35 y 216 ÷ 8 = 27.", "En total: 90 + 35 + 27 = 152 trozos."), theory = "Para cortar varias longitudes en trozos iguales sin que sobre nada, la longitud del trozo debe ser un divisor común. Para tener la menor cantidad de trozos, cada trozo debe ser lo más largo posible: el MCD.", idea = "Menos trozos significa trozos más largos, así que se usa el MCD y no cualquier divisor común.", mistake = "Usar un divisor común que no es el mayor. Con trozos de 4 m saldrían 1216 ÷ 4 = 304 trozos, que es la alternativa A, pero no es la cantidad mínima.", verify = "152 trozos de 8 m suman 1216 m, que es justo 720 + 280 + 216. No sobra material.", trap = "(720+280+216)/4", src = "oficial", year = 2023, num = 3, trapOpt = 0, official = 2))
        l.add(BProb(id = "e23_04", topic = "arit", level = 3, text = "Un comerciante compra lapiceros y borradores, los cuales distribuye en 5 cajas. En unas cajas hay lapiceros y en otras, borradores. La cantidad de unidades contenidas en cada caja son respectivamente 9, 8, 12, 23 y 27. Si el comerciante solo vendió todo el contenido de una de las cajas y de lo que le quedó se sabe que, la cantidad de lapiceros es el cuádruple de la cantidad de borradores, ¿cuántos lapiceros le quedaron al comerciante?", opts = listOf("70", "60", "48", "56"), vals = listOf("70", "60", "48", "56"), correct = 3, check = "4/5*(79-sum(select(k->irem(79-k,5)==0,[9,8,12,23,27])))", steps = listOf("En total hay 9 + 8 + 12 + 23 + 27 = 79 unidades.", "Si quedan L lapiceros y B borradores con L = 4B, lo que quedó es L + B = 5B, un múltiplo de 5.", "Probamos qué caja se pudo vender: 79 − 9 = 70, 79 − 8 = 71, 79 − 12 = 67, 79 − 23 = 56 y 79 − 27 = 52. Solo 70 es múltiplo de 5, así que se vendió la caja de 9.", "Entonces 5B = 70, B = 14 borradores y L = 4·14 = 56 lapiceros."), note = "Con las cajas que quedan, 8, 12, 23 y 27, ningún grupo suma exactamente 14 borradores. La clave oficial 56 sale del razonamiento de divisibilidad, que es lo que pide el examen.", theory = "Si una cantidad es el cuádruple de otra, juntas forman 4 + 1 = 5 partes iguales. Por eso su suma debe ser múltiplo de 5.", idea = "Lo que quedó debe ser múltiplo de 5. Eso indica qué caja se vendió.", mistake = "Responder con todo lo que quedó, 70 unidades, que es la alternativa A. Esa cantidad incluye lapiceros y borradores.", verify = "56 = 4·14 y 56 + 14 = 70, que es lo que quedó después de vender la caja de 9.", warn = "El enunciado oficial tiene una inconsistencia. Lee la nota de la solución.", trap = "79-9", src = "oficial", year = 2023, num = 4, trapOpt = 0, official = 3, review = true))
        l.add(BProb(id = "e23_05", topic = "arit", level = 1, text = "Tenía S/ 3000 compré un monitor y me quedó S/ 1960. Entonces recibí S/ 840 y luego compré un regalo y me quedó S/ 2200, ¿cuánto suma lo gastado en el monitor y el regalo?", opts = listOf("S/ 1640", "S/ 1540", "S/ 1840", "S/ 1340"), vals = listOf("1640", "1540", "1840", "1340"), correct = 0, check = "(3000-1960)+(1960+840-2200)", steps = listOf("Monitor: tenía S/ 3000 y quedó S/ 1960, así que gastó 3000 − 1960 = S/ 1040.", "Luego recibió S/ 840: 1960 + 840 = S/ 2800.", "Regalo: tenía S/ 2800 y quedó S/ 2200, así que gastó 2800 − 2200 = S/ 600.", "Suma de lo gastado: 1040 + 600 = S/ 1640."), theory = "Lo gastado en una compra es lo que se tenía antes menos lo que quedó después.", idea = "Cada gasto se calcula con lo que había justo antes de esa compra, no con los S/ 3000 iniciales.", mistake = "Calcular el regalo como 3000 − 2200 = 800, olvidando el gasto anterior y lo recibido. Así se obtiene 1040 + 800 = 1840, que es la alternativa C.", verify = "Otra forma: entró dinero por 3000 + 840 = 3840 y al final quedan 2200. Lo gastado es 3840 − 2200 = 1640.", trap = "(3000-1960)+(3000-2200)", src = "oficial", year = 2023, num = 5, trapOpt = 2, official = 0))
        l.add(BProb(id = "e23_06", topic = "porc", level = 2, text = "El sueldo semanal de un médico es 25 % más que el sueldo semanal de una enfermera y 50 % más que el sueldo semanal de un técnico en enfermería. Si la suma de los sueldos semanales de los tres es S/ 3700, ¿cuánto gana un técnico en enfermería semanalmente?", opts = listOf("S/ 1000", "S/ 1200", "S/ 900", "S/ 1500"), vals = listOf("1000", "1200", "900", "1500"), correct = 0, check = "solve(3/2*t+3/2*t*4/5+t=3700,t)[0]", steps = listOf("Sea T el sueldo del técnico. El médico gana 50 % más que el técnico: M = 1,5T.", "El médico también gana 25 % más que la enfermera: M = 1,25E. Entonces E = 1,5T ÷ 1,25 = 1,2T.", "La suma de los tres es 1,5T + 1,2T + T = 3,7T = 3700.", "Por lo tanto T = 3700 ÷ 3,7 = S/ 1000."), theory = "Ser un 25 % más que una cantidad es valer 125 % de ella, es decir 1,25 veces. Ser un 50 % más es valer 1,5 veces.", idea = "Conviene escribir los tres sueldos en función del técnico, que es lo que se pregunta.", mistake = "Detenerse en el sueldo de la enfermera, S/ 1200, que es la alternativa B. También aparece el del médico, S/ 1500, en la D.", verify = "Técnico 1000, enfermera 1200 y médico 1500. Suma 3700. Además 1500 es 25 % más que 1200 y 50 % más que 1000.", trap = "solve(3/2*t+3/2*t*4/5+t=3700,t)[0]*6/5", src = "oficial", year = 2023, num = 6, trapOpt = 1, official = 0))
        l.add(BProb(id = "e23_07", topic = "geo", level = 2, text = "Se desea diseñar una caja cúbica de volumen mínimo para almacenar cajitas, en donde cada cajita contiene 50 mascarillas descartables. Si las dimensiones de las cajitas son de 20 cm de largo, 10 cm de ancho y 8 cm de altura, ¿cuál es la cantidad de mascarillas que puede almacenar la caja cúbica, sin que sobre espacio?", opts = listOf("2000", "250", "1000", "2500"), vals = listOf("2000", "250", "1000", "2500"), correct = 0, check = "lcm(lcm(20,10),8)^3/(20*10*8)*50", steps = listOf("La arista del cubo debe ser múltiplo de 20, de 10 y de 8. El menor es MCM(20, 10, 8) = 40 cm.", "Volumen del cubo: 40³ = 64 000 cm³. Volumen de una cajita: 20·10·8 = 1600 cm³.", "Caben 64 000 ÷ 1600 = 40 cajitas. Se comprueba por filas: 40 ÷ 20 = 2, 40 ÷ 10 = 4 y 40 ÷ 8 = 5, y 2·4·5 = 40.", "Cada cajita trae 50 mascarillas: 40·50 = 2000 mascarillas."), theory = "Para llenar un cubo con cajitas iguales sin que sobre espacio, la arista del cubo debe ser múltiplo de las tres dimensiones de la cajita. La menor arista posible es el MCM.", idea = "Primero se halla la arista del cubo con el MCM; luego se cuentan cajitas por volumen.", mistake = "Tomar como arista la mayor medida, 20 cm. Saldrían 8000 ÷ 1600 = 5 cajitas y 250 mascarillas, que es la alternativa B, pero 20 no es múltiplo de 8 y sobraría espacio.", verify = "2·4·5 = 40 cajitas llenan exactamente el cubo de 40 cm, y 40·50 = 2000.", trap = "20^3/(20*10*8)*50", src = "oficial", year = 2023, num = 7, trapOpt = 1, official = 0))
        l.add(BProb(id = "e23_08", topic = "prob", level = 2, text = "Danny tiene en su granja una coneja que está preñada, el veterinario al revisarla, comprobó que hay tres conejitos en su vientre. Si todo ocurre con normalidad, ¿cuál es la probabilidad de que el día del alumbramiento de los conejitos, nazcan por lo menos dos conejitos machos?", opts = listOf("§3/4", "§3/8", "§1/2", "§1/4"), vals = listOf("3/4", "3/8", "1/2", "1/4"), correct = 2, check = "(binomial(3,2)+binomial(3,3))/2^3", steps = listOf("Cada conejito tiene 2 posibilidades, así que hay 2³ = 8 resultados posibles.", "Exactamente dos machos: se elige cuál es la hembra, 3 formas: MMH, MHM y HMM.", "Exactamente tres machos: 1 forma, MMM.", "Casos favorables: 3 + 1 = 4. Probabilidad: 4/8 = 1/2."), theory = "Si cada resultado es igualmente probable, la probabilidad es casos favorables entre casos posibles. Cada conejito puede ser macho o hembra con la misma probabilidad.", idea = "Por lo menos dos machos significa exactamente dos o exactamente tres.", mistake = "Contar solo exactamente dos machos: 3/8, que es la alternativa B.", verify = "Por simetría, tener al menos dos machos es tan probable como tener al menos dos hembras, y esos dos sucesos no pueden darse a la vez. Cada uno vale 1/2.", trap = "binomial(3,2)/2^3", src = "oficial", year = 2023, num = 8, trapOpt = 1, official = 2))
