    private fun p1(l: MutableList<BProb>) {
        l.add(BProb(id = "e23_09", topic = "prob", level = 2, text = "En el curso de Cálculo I de la Escuela de Matemáticas de cierta universidad, se sabe que asisten a clases 30 de los 40 matriculados, además se sabe que de los alumnos que asisten a clases aprueban el 70% y de los que no asisten a clases el 20%. Si se elige un alumno al azar, ¿cuál es la probabilidad de que haya aprobado este curso?", opts = listOf("0,575", "0,325", "0,550", "0,900"), vals = listOf("575/1000", "325/1000", "550/1000", "900/1000"), correct = 0, check = "30/40*70/100+10/40*20/100", steps = listOf("Asisten 30 de 40, que es 0,75 del total. No asisten 10 de 40, que es 0,25.", "Aprueban de los que asisten: 70 % de 30 = 21 alumnos.", "Aprueban de los que no asisten: 20 % de 10 = 2 alumnos.", "Aprueban 21 + 2 = 23 de 40. Probabilidad: 23/40 = 0,575."), theory = "Probabilidad total: si los alumnos se dividen en grupos, la probabilidad de aprobar es la suma de lo que aporta cada grupo, es decir su fracción del total por su probabilidad de aprobar.", idea = "Cada porcentaje de aprobados se aplica solo a su grupo, no a los 40.", mistake = "Sumar los dos porcentajes sin ponderar por el tamaño de cada grupo: 0,70 + 0,20 = 0,900, que es la alternativa D.", verify = "Con la fórmula: 0,75·0,70 + 0,25·0,20 = 0,525 + 0,05 = 0,575.", trap = "70/100+20/100", src = "oficial", year = 2023, num = 9, trapOpt = 3, official = 0))
        l.add(BProb(id = "e23_10", topic = "porc", level = 2, text = "De un grupo de personas que se presentaron a un concurso, el 40 % no pasó el examen de aptitud. Las personas que sí aprobaron fueron divididas en dos grupos de igual cantidad para la entrevista personal. Del primer grupo aprobaron el 35 % y del segundo el 45 %. En relación con la cantidad de personas que se presentaron, ¿qué porcentaje aprobaron la entrevista?", opts = listOf("16%", "23%", "24%", "26%"), vals = listOf("16", "23", "24", "26"), correct = 2, check = "60/2*35/100+60/2*45/100", steps = listOf("Supongamos que se presentaron 100 personas. No pasaron la aptitud 40, así que pasaron 60.", "Los 60 se dividen en dos grupos iguales de 30.", "Del primer grupo aprueban 35 % de 30 = 10,5. Del segundo, 45 % de 30 = 13,5.", "Aprueban la entrevista 10,5 + 13,5 = 24 de 100, es decir 24 %."), theory = "Un porcentaje de un porcentaje se calcula multiplicando. Conviene suponer que se presentaron 100 personas.", idea = "Cada grupo de entrevista es la mitad del 60 % que aprobó la aptitud, es decir 30 % del total.", mistake = "Aplicar 35 % y 45 % a todos los presentados o sumarlos sin dividir los grupos. Ninguna alternativa recoge un error típico claro.", verify = "Como los grupos son iguales, el porcentaje de aprobados en la entrevista es el promedio (35 + 45)/2 = 40 % de los 60, y 40 % de 60 es 24.", src = "oficial", year = 2023, num = 10, official = 2))
        l.add(BProb(id = "e23_11", topic = "alg", level = 2, text = "Dados los polinomios p(x) = x⁶ + 2x⁴ + 2x² + 1 y q(x) = x⁴ + x³ + 2x² + x + 1, calcule el cociente al dividir p(x) entre q(x).", opts = listOf("x² + x + 1", "x² – x – 1", "x² + x – 1", "x² – x + 1"), vals = listOf("x^2+x+1", "x^2-x-1", "x^2+x-1", "x^2-x+1"), correct = 3, check = "quo(x^6+2*x^4+2*x^2+1,x^4+x^3+2*x^2+x+1,x)", steps = listOf("Ordenamos p(x) completo: x⁶ + 0x⁵ + 2x⁴ + 0x³ + 2x² + 0x + 1.", "Primer término del cociente: x⁶ ÷ x⁴ = x². Restamos x²·q(x) = x⁶ + x⁵ + 2x⁴ + x³ + x² y queda −x⁵ + 0x⁴ − x³ + x² + 0x + 1.", "Segundo término: −x⁵ ÷ x⁴ = −x. Restamos −x·q(x) = −x⁵ − x⁴ − 2x³ − x² − x y queda x⁴ + x³ + 2x² + x + 1.", "Tercer término: x⁴ ÷ x⁴ = 1. Restamos 1·q(x) y el residuo es 0.", "El cociente es x² − x + 1."), calc = "quo(x^6+2*x^4+2*x^2+1,x^4+x^3+2*x^2+x+1,x)", theory = "En la división de polinomios, el dividendo es igual al divisor por el cociente más el residuo. El grado del cociente es el grado del dividendo menos el del divisor.", idea = "El cociente tiene grado 6 − 4 = 2. Se completan con ceros los términos que faltan en p(x).", mistake = "Equivocarse con un signo al restar en el segundo paso. Por eso las cuatro alternativas solo difieren en los signos.", verify = "Multiplicando: (x² − x + 1)(x⁴ + x³ + 2x² + x + 1) = x⁶ + 2x⁴ + 2x² + 1, que es p(x). La división es exacta.", src = "oficial", year = 2023, num = 11, official = 3))
        l.add(BProb(id = "e23_12", topic = "ecu", level = 1, text = "En un juego de ajedrez, se plantea la siguiente regla: cada vez que un jugador gane una partida recibe S/ 10 y cada vez que pierde paga S/ 4. En un total de 12 partidas, un jugador ha ganado S/ 64, ¿cuántas partidas ganó?", opts = listOf("6", "8", "4", "2"), vals = listOf("6", "8", "4", "2"), correct = 1, check = "solve(10*g-4*(12-g)=64,g)[0]", steps = listOf("Sea g el número de partidas ganadas. Entonces perdió 12 − g.", "Recibe 10g y paga 4(12 − g). Lo que gana neto es 10g − 4(12 − g) = 64.", "Desarrollamos: 10g − 48 + 4g = 64, así que 14g = 112.", "g = 8 partidas ganadas."), theory = "Un planteo con dos tipos de resultados se resuelve con una incógnita: si gana g partidas, pierde el resto.", idea = "Lo que gana neto es lo recibido por ganar menos lo pagado por perder.", mistake = "Responder las partidas perdidas, 12 − 8 = 4, que es la alternativa C.", verify = "Ganó 8: recibe 80. Perdió 4: paga 16. Neto 80 − 16 = 64.", trap = "12-solve(10*g-4*(12-g)=64,g)[0]", src = "oficial", year = 2023, num = 12, trapOpt = 2, official = 1))
        l.add(BProb(id = "e23_13", topic = "arit", level = 1, text = "Oxana tiene un pendrive de 32Gb de capacidad, al parecer un virus lo ha contaminado y desea salvar su contenido cuanto antes. Los archivos guardados tienen un tamaño que varían de 50Mb a 70Mb(1Gb = 1024Mb). ¿Cuál es el número máximo de archivos que potencialmente puede salvar?", opts = listOf("655", "468", "474", "642"), vals = listOf("655", "468", "474", "642"), correct = 0, check = "floor(32*1024/50)", steps = listOf("Capacidad: 32 Gb = 32·1024 = 32 768 Mb.", "Para tener la mayor cantidad posible, suponemos que todos pesan lo mínimo, 50 Mb.", "32 768 ÷ 50 = 655,36.", "Solo cuentan archivos completos: como máximo 655."), theory = "Para que quepa la mayor cantidad de archivos, cada archivo debe ser lo más pequeño posible. Solo cuentan los archivos completos, así que se toma la parte entera.", idea = "Máximo número de archivos significa usar el tamaño mínimo, 50 Mb.", mistake = "Dividir entre el tamaño máximo, 70 Mb. Eso da 468, que es la alternativa B, pero es el número mínimo garantizado, no el máximo.", verify = "655·50 = 32 750 Mb, que cabe en 32 768. Con 656 archivos se necesitarían 32 800 Mb, que no caben.", trap = "floor(32*1024/70)", src = "oficial", year = 2023, num = 13, trapOpt = 1, official = 0))
        l.add(BProb(id = "e23_14", topic = "alg", level = 3, text = "Simplificar la expresión:\n§E=(surd(3^x+5^(-x),x)+surd(3^(-x)+5^x,x))/surd(15^x+1,x)", opts = listOf("§16/15", "§4/5", "§2/15", "§8/15"), vals = listOf("16/15", "4/5", "2/15", "8/15"), correct = 3, check = "(surd(3^2+5^(-2),2)+surd(3^(-2)+5^2,2))/surd(15^2+1,2)", steps = listOf("Primer radicando: 3ˣ + 5⁻ˣ = 3ˣ + 1/5ˣ = (15ˣ + 1)/5ˣ, porque 3ˣ·5ˣ = 15ˣ.", "Su raíz de índice x es la raíz de (15ˣ + 1) dividida entre la raíz de 5ˣ, es decir la raíz de (15ˣ + 1) entre 5.", "Segundo radicando: 3⁻ˣ + 5ˣ = (1 + 15ˣ)/3ˣ. Su raíz de índice x es la raíz de (15ˣ + 1) entre 3.", "Al dividir el numerador entre la raíz de (15ˣ + 1), ese factor se cancela y queda 1/5 + 1/3.", "1/5 + 1/3 = 3/15 + 5/15 = 8/15."), theory = "Leyes de exponentes: a⁻ˣ = 1/aˣ y la raíz de índice x de un cociente es el cociente de las raíces. Además la raíz de índice x de aˣ es a.", idea = "Cada suma de adentro se puede escribir con 15ˣ + 1 en el numerador. Así aparece el mismo factor que en el denominador.", mistake = "Pensar que la raíz de una suma es la suma de las raíces. Ese error no lleva a ninguna alternativa en particular.", verify = "Con x = 2: la raíz cuadrada de 9 + 1/25 es la raíz de 226 entre 5, la de 1/9 + 25 es la raíz de 226 entre 3, y al dividir entre la raíz de 226 se obtiene 1/5 + 1/3 = 8/15.", src = "oficial", year = 2023, num = 14, official = 3))
        l.add(BProb(id = "e23_15", topic = "alg", level = 3, text = "El número de unidades de un artículo A, que los productores están dispuestos a proveer al mercado de abastos, cuando el precio de este artículo es x soles, está dada por la función f(x) = x² − bx + 10, x ≥ 3. En la siguiente tabla se muestran algunos valores que toma la función f(x).\n[tabla]\nSi el precio del artículo A fuese 35 soles ¿con cuántas unidades del artículo A, los productores estarían dispuestos a proveer al mercado de abastos?", opts = listOf("631", "847", "1025", "1015"), vals = listOf("631", "847", "1025", "1015"), correct = 2, check = "subs(x^2-b*x+10,[x,b],[35,solve(subs(x^2-b*x+10,x=10)=10*subs(x^2-b*x+10,x=5),b)[0]])", steps = listOf("De la tabla: f(5) = α y f(10) = 10α. Entonces f(10) = 10·f(5).", "f(5) = 25 − 5b + 10 = 35 − 5b y f(10) = 100 − 10b + 10 = 110 − 10b.", "110 − 10b = 10(35 − 5b) = 350 − 50b, así que 40b = 240 y b = 6.", "La función es f(x) = x² − 6x + 10. Para x = 35: 35² − 6·35 + 10 = 1225 − 210 + 10 = 1025."), theory = "Evaluar una función es reemplazar x por el número. Si se conocen dos valores relacionados, se plantea una ecuación para hallar el coeficiente desconocido.", idea = "La tabla dice que f(10) es diez veces f(5). Con eso se halla b.", mistake = "Olvidar el término + 10 al evaluar: 1225 − 210 = 1015, que es la alternativa D.", verify = "Con b = 6: f(5) = 5 y f(10) = 50, que sí es diez veces f(5).", trap = "35^2-6*35", src = "oficial", table = listOf(listOf("x", "5", "10"), listOf("f(x)", "α", "10α")), year = 2023, num = 15, trapOpt = 3, official = 2))
        l.add(BProb(id = "e23_16", topic = "ineq", level = 3, text = "Una empresa distribuye semanalmente protectores faciales al sector salud, la cantidad total de protectores faciales que debe distribuir semanalmente debe ser menor que 427. Si en la semana ya se han distribuido 90 protectores faciales, y quedan por distribuir una cantidad mayor a los tres quintos del total, más 78 protectores faciales, ¿Cuál es la cantidad mínima de protectores faciales que se distribuyeron en la semana?", opts = listOf("421", "426", "424", "420"), vals = listOf("421", "426", "424", "420"), correct = 0, check = "floor(solve(t-90=3/5*t+78,t)[0])+1", steps = listOf("Sea T el total de la semana. Primera condición: T < 427.", "Ya se distribuyeron 90, así que faltan T − 90. Segunda condición: T − 90 > (3/5)T + 78.", "Pasamos términos: T − (3/5)T > 78 + 90, es decir (2/5)T > 168, de donde T > 420.", "Juntando: 420 < T < 427. Los enteros posibles son 421, 422, …, 426. El mínimo es 421."), theory = "Una inecuación se resuelve como una ecuación, pero el resultado es un intervalo. Si la incógnita cuenta objetos, solo valen enteros.", idea = "Se plantean dos condiciones sobre el total T: una dada directamente y otra con lo que falta distribuir.", mistake = "Tomar el mayor valor posible, 426, que es la alternativa B, en lugar del mínimo.", verify = "Con T = 421 faltan 331, y (3/5)·421 + 78 = 330,6. Como 331 > 330,6 se cumple. Con T = 420 faltarían 330, que no es mayor que 330.", trap = "427-1", src = "oficial", year = 2023, num = 16, trapOpt = 1, official = 0))
    }
    private fun p2(l: MutableList<BProb>) {
        l.add(BProb(id = "e23_17", topic = "ineq", level = 3, text = "Un comerciante tiene 3000 unidades de un producto cuyo precio unitario es de \$ 5, y tiene proyectado que el próximo mes el precio del producto se incremente en \$ 0,5. Si el comerciante quiere que el ingreso total por la venta de las 3000 unidades no sea menor que \$ 15 900. ¿Cuál es el ingreso máximo que puede obtener por la venta de dicho producto durante estos dos meses?", opts = listOf("\$ 5995", "\$ 6000", "\$ 6005", "\$ 4000"), vals = listOf("5995", "6000", "6005", "4000"), correct = 1, check = "5*solve(5*u+11/2*(3000-u)=15900,u)[0]", steps = listOf("Sea u el número de unidades vendidas este mes a \$ 5. El resto, 3000 − u, se vende el próximo mes a \$ 5,5.", "Ingreso total: 5u + 5,5(3000 − u) = 16 500 − 0,5u.", "Condición: 16 500 − 0,5u ≥ 15 900, así que 0,5u ≤ 600 y u ≤ 1200.", "Lo más que puede vender este mes son 1200 unidades, y el ingreso de este mes es como máximo 5·1200 = \$ 6000. Esa es la clave oficial."), note = "El enunciado dice durante estos dos meses, pero la clave B corresponde al ingreso máximo del primer mes. El ingreso de los dos meses juntos sería como máximo \$ 16 500, que no está entre las opciones.", theory = "Una condición de no ser menor que se escribe con mayor o igual. Si una cantidad depende de la incógnita, su máximo ocurre en el extremo del intervalo permitido.", idea = "Las unidades que se venden este mes a \$ 5 dejan de venderse el próximo mes a \$ 5,5. Vender pronto baja el ingreso total.", mistake = "Calcular el ingreso de los dos meses juntos. Ese valor no aparece entre las opciones.", verify = "Con u = 1200: el ingreso total es 6000 + 1800·5,5 = 6000 + 9900 = 15 900, justo el mínimo pedido. Con 1201 unidades bajaría de 15 900.", warn = "La redacción oficial es ambigua. La clave corresponde al ingreso del primer mes.", src = "oficial", year = 2023, num = 17, official = 1, review = true))
        l.add(BProb(id = "e23_18", topic = "alg", level = 2, text = "Si x es solución de la ecuación\n§(x-2)/(x+2)+(x+2)/(x-2)=3\nentonces el valor de x⁴ − 19x² + 18.", opts = listOf("– 72", "38", "– 42", "60"), vals = listOf("-72", "38", "-42", "60"), correct = 1, check = "subs(x^4-19*x^2+18,x=max(solve((x-2)/(x+2)+(x+2)/(x-2)=3,x)))", steps = listOf("Común denominador x² − 4: [(x − 2)² + (x + 2)²]/(x² − 4) = 3.", "El numerador es (x² − 4x + 4) + (x² + 4x + 4) = 2x² + 8.", "Entonces 2x² + 8 = 3(x² − 4) = 3x² − 12, de donde x² = 20.", "Reemplazamos: x⁴ − 19x² + 18 = 20² − 19·20 + 18 = 400 − 380 + 18 = 38."), theory = "Para sumar fracciones algebraicas se usa el común denominador. Aquí (x + 2)(x − 2) = x² − 4.", idea = "No hace falta hallar x: basta con hallar x², porque la expresión pedida solo tiene x⁴ y x².", mistake = "Desarrollar mal (x − 2)² + (x + 2)² y obtener otro valor de x². Ninguna alternativa recoge un error típico claro.", verify = "x² = 20 no anula el denominador, porque x² − 4 = 16. Con x = √20: (x − 2)/(x + 2) + (x + 2)/(x − 2) = 48/16 = 3.", src = "oficial", year = 2023, num = 18, official = 1))
        l.add(BProb(id = "e23_19", topic = "geo", level = 3, text = "Una fábrica de empaques desea confeccionar cajas con bases rectangulares de cartón sin tapa para frutas, cada una de ellas con capacidad de 26 250 cm³. Para cada caja se cuenta con una lámina rectangular de cartón cuyo largo es 45 cm más que su ancho. La caja se confecciona cortando en cada esquina cuadrados de 15 cm de lado y luego doblando los bordes. Calcule el área de la lámina rectangular de cartón.", opts = listOf("5500 cm²", "3400 cm²", "4050 cm²", "6300 cm²"), vals = listOf("5500", "3400", "4050", "6300"), correct = 0, check = "max(solve((w-30)*(w+15)=1750,w))*(max(solve((w-30)*(w+15)=1750,w))+45)", steps = listOf("Sea a el ancho de la lámina. Su largo es a + 45.", "La base de la caja mide (a − 30) por (a + 45 − 30) = (a − 30)(a + 15), y la altura es 15.", "Volumen: 15(a − 30)(a + 15) = 26 250, así que (a − 30)(a + 15) = 1750.", "Desarrollamos: a² − 15a − 450 = 1750, es decir a² − 15a − 2200 = 0, que se factoriza como (a − 55)(a + 40) = 0. Como a es positivo, a = 55.", "La lámina mide 55 por 100. Área: 5500 cm²."), note = "En el examen oficial las alternativas están rotuladas A, B, D y E. No hay alternativa C.", theory = "Al cortar cuadrados de lado c en las esquinas y doblar, la caja tiene altura c, y a cada medida de la lámina se le restan 2c.", idea = "La altura de la caja es 15 cm y la base mide 30 cm menos por lado.", mistake = "Restar solo 15 cm a cada medida en lugar de 30. Ese error no lleva a ninguna alternativa.", verify = "La caja mide 25 por 70 de base y 15 de alto: 25·70·15 = 26 250 cm³.", letters = "ABDE", src = "oficial", year = 2023, num = 19, official = 0))
        l.add(BProb(id = "e23_20", topic = "ecu", level = 2, text = "En el diagrama, los dos platos de cada balanza se encuentran en equilibrio. Si figuras iguales tienen el mismo peso y cada cilindro pesa 1 kg, ¿cuántos cubos juntos tienen el mismo el peso que una esfera?", opts = listOf("8", "3", "7", "2"), vals = listOf("8", "3", "7", "2"), correct = 0, check = "linsolve([2*c+s=2,2*s-c=3],[c,s])[1]/linsolve([2*c+s=2,2*s-c=3],[c,s])[0]", steps = listOf("Sea c el peso de un cubo y e el de una esfera, en kg. Cada cilindro pesa 1 kg.", "Primera balanza: 2 cilindros = 2 cubos + 1 esfera, es decir 2 = 2c + e.", "Segunda balanza: 3 cilindros + 1 cubo = 2 esferas, es decir 3 + c = 2e.", "De la primera, e = 2 − 2c. En la segunda: 3 + c = 4 − 4c, así que 5c = 1 y c = 1/5 kg. Luego e = 2 − 2/5 = 8/5 kg.", "Una esfera equivale a (8/5) ÷ (1/5) = 8 cubos."), fig = "x23_20", theory = "Una balanza en equilibrio es una ecuación: lo que pesa un plato es igual a lo que pesa el otro. Dos balanzas forman un sistema.", idea = "Se escribe una ecuación por balanza y luego se compara el peso de una esfera con el de un cubo.", mistake = "Responder el peso de la esfera en kg, 8/5, o el de un cubo, en lugar de cuántos cubos equivalen a una esfera.", verify = "Primera: 2·(1/5) + 8/5 = 2. Segunda: 3 + 1/5 = 16/5 = 2·(8/5). Ambas balanzas quedan equilibradas.", src = "oficial", year = 2023, num = 20, official = 0))
        l.add(BProb(id = "e23_21", topic = "geo", level = 2, text = "Sofía preparó una torta con forma de cilindro circular recto de 30 cm de diámetro y 10 cm de altura para compartir con sus 15 invitados. Ella distribuyó 20 cerezas sobre la torta en forma de una circunferencia concéntrica a la torta. La torta se dividió en partes iguales y en cada porción había una cereza, como se muestra en la figura. Si Sofía y sus 15 invitados en la reunión comieron solo una porción, halle el volumen de la torta sobrante.", opts = listOf("600π cm³", "562,5π cm³", "500π cm³", "450π cm³"), vals = listOf("600*pi", "1125*pi/2", "500*pi", "450*pi"), correct = 3, check = "pi*15^2*10*(20-16)/20", steps = listOf("El diámetro es 30 cm, así que el radio es 15 cm. La figura lo confirma: el borde recto de la porción mide 15 cm.", "Volumen total: π·15²·10 = π·225·10 = 2250π cm³.", "Hay 20 cerezas y una en cada porción: la torta tiene 20 porciones iguales de 2250π ÷ 20 = 112,5π cm³.", "Comieron 1 + 15 = 16 personas, una porción cada una. Sobran 20 − 16 = 4 porciones.", "Volumen sobrante: 4·112,5π = 450π cm³."), fig = "x23_21", theory = "El volumen de un cilindro es V = π·r²·h. Si se corta en n porciones iguales, cada porción mide V/n.", idea = "Una cereza por porción significa 20 porciones. Comieron Sofía más sus 15 invitados, es decir 16 personas.", mistake = "Olvidar contar a Sofía y pensar que comieron 15. Sobrarían 5 porciones, 562,5π cm³, que es la alternativa B.", verify = "Lo comido más lo sobrante da el total: 16·112,5π + 4·112,5π = 1800π + 450π = 2250π cm³.", trap = "pi*15^2*10*(20-15)/20", src = "oficial", year = 2023, num = 21, trapOpt = 1, official = 3))
        l.add(BProb(id = "e23_22", topic = "geo", level = 3, text = "En la figura, ABC es un triángulo rectángulo de un cateto igual a 16 e hipotenusa 20. Si L es el lado del cuadrado inscrito, calcular la suma de las áreas de los triángulos interiores.", opts = listOf("§2160/49", "48", "§2400/49", "§2592/49"), vals = listOf("2160/49", "48", "2400/49", "2592/49"), correct = 2, check = "16*12/2-(16*12/(16+12))^2", steps = listOf("Por Pitágoras, el otro cateto es BC = √(20² − 16²) = √144 = 12.", "El vértice del cuadrado sobre la hipotenusa cumple semejanza: el triángulo de arriba tiene catetos 16 − L y L, semejante al grande. Entonces (16 − L)/L = 16/12, de donde L = 16·12/28 = 48/7.", "Área del triángulo grande: 16·12/2 = 96. Área del cuadrado: (48/7)² = 2304/49.", "Suma de los triángulos interiores: 96 − 2304/49 = 4704/49 − 2304/49 = 2400/49."), fig = "x23_22", note = "En el original la alternativa C aparece escrita 2,400/49. La coma separa los miles: es 2400/49.", theory = "Teorema de Pitágoras para el cateto que falta. En un triángulo rectángulo con un cuadrado inscrito en el ángulo recto, el lado del cuadrado es L = ab/(a + b), donde a y b son los catetos.", idea = "Los dos triángulos interiores son lo que queda del triángulo grande al quitar el cuadrado.", mistake = "Tomar L igual a la mitad de un cateto, 8 o 6, en lugar de ab/(a + b). Ese error no lleva a ninguna alternativa.", verify = "Calculando cada triángulo: L(16 − L)/2 + L(12 − L)/2 = L(28 − 2L)/2 = L(14 − L) = (48/7)(50/7) = 2400/49.", src = "oficial", year = 2023, num = 22, official = 2))
        l.add(BProb(id = "e23_23", topic = "geo", level = 2, text = "En un triángulo rectángulo sus catetos miden 2x – 1, 2(x + 1) y la hipotenusa 3x. Halle el área del triángulo.", opts = listOf("54", "35", "77", "43"), vals = listOf("54", "35", "77", "43"), correct = 0, check = "subs((2*x-1)*(2*x+2)/2,x=max(solve((2*x-1)^2+(2*x+2)^2=9*x^2,x)))", steps = listOf("Pitágoras: (2x − 1)² + (2x + 2)² = (3x)².", "Desarrollamos: 4x² − 4x + 1 + 4x² + 8x + 4 = 9x², es decir 8x² + 4x + 5 = 9x².", "Queda x² − 4x − 5 = 0, que se factoriza como (x − 5)(x + 1) = 0. Como las medidas son positivas, x = 5.", "Catetos: 2·5 − 1 = 9 y 2·6 = 12. Hipotenusa 15.", "Área: 9·12/2 = 54."), theory = "Teorema de Pitágoras: la suma de los cuadrados de los catetos es el cuadrado de la hipotenusa. El área de un triángulo rectángulo es el producto de los catetos entre 2.", idea = "Con Pitágoras se halla x, y con x los catetos.", mistake = "Olvidar dividir entre 2 y obtener 108, o usar la hipotenusa como cateto. Ninguna alternativa recoge esos errores.", verify = "9² + 12² = 81 + 144 = 225 = 15². Es el triángulo 3, 4, 5 multiplicado por 3.", src = "oficial", year = 2023, num = 23, official = 0))
        l.add(BProb(id = "e23_24", topic = "geo", level = 2, text = "En el triángulo ABC que se muestra en la figura, BD = 2 y DC = 6. Calcule el valor numérico de AC² – AB².", opts = listOf("32", "16", "40", "18"), vals = listOf("32", "16", "40", "18"), correct = 0, check = "6^2-2^2", steps = listOf("En el triángulo ADC, recto en D: AC² = AD² + DC² = AD² + 36.", "En el triángulo ADB, recto en D: AB² = AD² + BD² = AD² + 4.", "Restamos: AC² − AB² = 36 − 4 = 32."), fig = "x23_24", theory = "Teorema de Pitágoras en cada triángulo rectángulo que forma la altura AD.", idea = "La altura AD es común a los dos triángulos, así que se cancela al restar.", mistake = "Sumar en lugar de restar: 36 + 4 = 40, que es la alternativa C.", verify = "Con el ángulo recto en A además se cumple AD² = BD·DC = 12. Entonces AC² = 48 y AB² = 16, y 48 − 16 = 32.", trap = "6^2+2^2", src = "oficial", year = 2023, num = 24, trapOpt = 2, official = 0))
    }
    private fun p3(l: MutableList<BProb>) {
        l.add(BProb(id = "e23_25", topic = "geo", level = 3, text = "La gráfica representa una cochera rodeada de un jardín, donde ABCD es un cuadrado. Si la parte sombreada es el jardín de 2 m de ancho y 130 m² de área, halle el perímetro del jardín.", opts = listOf("122", "134", "92", "115"), vals = listOf("122", "134", "92", "115"), correct = 1, check = "subs(3*s+4+2*(s-2)+(s-4),s=solve(6*s-8=130,s)[0])", steps = listOf("Sea s el lado del cuadrado ABCD. El jardín mide 2 m de ancho a la izquierda, a la derecha y arriba.", "La cochera con su entrada es el rectángulo PQSR: mide s − 4 de ancho y s − 2 de alto.", "Área del jardín: s² − (s − 4)(s − 2) = s² − (s² − 6s + 8) = 6s − 8 = 130, así que s = 23.", "Borde del jardín: por fuera AB + BC + CD = 3·23 = 69, y los tramos AR y SD de 2 m cada uno.", "Por dentro: RP = 21, PQ = 19 y QS = 21.", "Perímetro: 69 + 4 + 21 + 19 + 21 = 134."), fig = "x23_25", theory = "El área de una región con hueco es el área exterior menos el área del hueco. El perímetro de una región es la longitud de todo su borde, el de afuera y el de adentro.", idea = "El jardín rodea a la cochera por tres lados. Por abajo la cochera llega hasta el lado AD.", mistake = "Contar solo el borde exterior del cuadrado, 4·23 = 92, que es la alternativa C.", verify = "Con s = 23: 23² − 19·21 = 529 − 399 = 130 m², que es el área dada.", trap = "4*solve(6*s-8=130,s)[0]", src = "oficial", year = 2023, num = 25, trapOpt = 2, official = 1))
        l.add(BProb(id = "e23_26", topic = "geo", level = 2, text = "En la figura, se tiene dos círculos concéntricos de centro O y AB una cuerda tangente a uno de ellos. Si el área de la región sombreada es 64π m², halle AB.", opts = listOf("16 m", "14 m", "8 m", "8√2 m"), vals = listOf("16", "14", "8", "8*sqrt(2)"), correct = 0, check = "2*sqrt(64)", steps = listOf("Sean R el radio grande, r el pequeño y T el punto de tangencia. OT = r es perpendicular a AB y T es punto medio de AB.", "En el triángulo OTA, recto en T: AT² = OA² − OT² = R² − r².", "Área sombreada: π(R² − r²) = 64π, así que R² − r² = 64.", "Entonces AT² = 64, AT = 8 y AB = 2·8 = 16 m."), fig = "x23_26", theory = "Una cuerda del círculo grande que es tangente al pequeño se divide en dos mitades iguales en el punto de tangencia, y el radio pequeño es perpendicular a ella. El área de la corona es π(R² − r²).", idea = "Por Pitágoras, la mitad de la cuerda al cuadrado es R² − r², justo lo que aparece en el área de la corona.", mistake = "Quedarse con la mitad de la cuerda, 8 m, que es la alternativa C.", verify = "Por ejemplo, con r = 6 y R = 10 se tiene R² − r² = 64 y la cuerda tangente mide 2·8 = 16. El resultado no depende de los radios.", trap = "sqrt(64)", src = "oficial", year = 2023, num = 26, trapOpt = 2, official = 0))
        l.add(BProb(id = "e23_27", topic = "geo", level = 3, text = "El lado del cuadrado ABCD mide 4 cm. M es el punto medio de BC, N es el punto medio de AM y P es el punto medio de NC. Calcule el área del cuadrilátero ANPD.", opts = listOf("7 cm²", "8 cm²", "9 cm²", "6 cm²"), vals = listOf("7", "8", "9", "6"), correct = 0, check = "abs((0*1-2*0)+(2*5/2-3*1)+(3*4-0*5/2)+(0*0-0*4))/2", steps = listOf("Colocamos A(0; 0), B(4; 0), C(4; 4) y D(0; 4).", "M es punto medio de BC: M(4; 2). N es punto medio de AM: N(2; 1). P es punto medio de NC: P(3; 2,5).", "Fórmula del zapato con A, N, P, D: 0·1 − 2·0 = 0; 2·2,5 − 3·1 = 2; 3·4 − 0·2,5 = 12; 0·0 − 0·4 = 0.", "Suma 14. Área: 14 ÷ 2 = 7 cm²."), fig = "x23_27", theory = "Área de un polígono con coordenadas, fórmula del zapato: la mitad del valor absoluto de la suma de xᵢ·yᵢ₊₁ − xᵢ₊₁·yᵢ. El punto medio de dos puntos es el promedio de sus coordenadas.", idea = "Se ubica el cuadrado en un sistema de coordenadas y se calculan los puntos medios.", mistake = "Confundir los vértices B y C por el rótulo repetido de la figura y ubicar mal M.", verify = "Por áreas: triángulo AND más triángulo NPD. AND tiene base AD = 4 y altura 2, área 4. NPD: con la misma fórmula, 3. Total 7.", warn = "En la figura oficial el vértice de abajo a la derecha está rotulado C. Por el enunciado es B.", src = "oficial", year = 2023, num = 27, official = 0, review = true))
        l.add(BProb(id = "e23_28", topic = "geo", level = 3, text = "En la figura, las rectas L1 y L2 son paralelas, BC y BA son bisectrices de NCQ y MAQ respectivamente. Si mNBC = 40º, halle mMBA.", opts = listOf("50º", "40º", "95º", "100º"), vals = listOf("50", "40", "95", "100"), correct = 2, check = "180-40-90/2", steps = listOf("Sea ∠NCQ = 2a, así que ∠NCB = ∠BCQ = a. Sea ∠MAQ = 2b, así que ∠MAB = ∠BAQ = b.", "Vértice Q entre las paralelas: ∠CQA = ∠NCQ + ∠MAQ. Como ∠CQA = 90°, 2a + 2b = 90° y a + b = 45°.", "Vértice B entre las paralelas: ∠CBA = ∠NCB + ∠MAB = a + b = 45°.", "N, B y M están en una recta, así que ∠NBC + ∠CBA + ∠ABM = 180°: 40° + 45° + ∠MBA = 180°.", "∠MBA = 95°."), fig = "x23_28", theory = "Propiedad de las paralelas: si entre dos rectas paralelas se forma una línea quebrada con un vértice, el ángulo en ese vértice es igual a la suma de los ángulos que forman sus lados con las paralelas.", idea = "La propiedad se aplica dos veces, en Q y en B, y luego se usa que N, B y M están en línea recta.", mistake = "Creer que el ángulo pedido es igual al dado por estar en posiciones parecidas: 40°, alternativa B.", verify = "Los tres ángulos en B suman 40° + 45° + 95° = 180°, como debe ser en un ángulo llano.", src = "oficial", year = 2023, num = 28, official = 2))
        l.add(BProb(id = "e23_29", topic = "geo", level = 1, text = "En un triángulo rectángulo ABC (B = 90°), la suma relativa a la hipotenusa determina sobre ella dos segmentos de longitud 4 y 9 cm. Calcule el área de la región triangular ABC.", opts = listOf("39", "52", "42", "45"), vals = listOf("39", "52", "42", "45"), correct = 0, check = "13*sqrt(4*9)/2", steps = listOf("La altura trazada desde B divide a la hipotenusa en segmentos de 4 y 9. La hipotenusa mide 4 + 9 = 13.", "Altura: h² = 4·9 = 36, así que h = 6.", "Área: base por altura entre 2: 13·6/2 = 39."), theory = "Relación métrica: en un triángulo rectángulo, la altura relativa a la hipotenusa cumple h² = m·n, donde m y n son las proyecciones de los catetos sobre la hipotenusa.", idea = "Los segmentos 4 y 9 son las proyecciones. Con ellos se obtiene la altura.", mistake = "Olvidar dividir entre 2 y obtener 78, que no aparece entre las opciones.", verify = "Los catetos miden √(4·13) = √52 y √(9·13) = √117. Su producto entre 2 es √(52·117)/2 = 78/2 = 39.", warn = "El original dice la suma relativa a la hipotenusa. Se refiere a la altura relativa a la hipotenusa.", src = "oficial", year = 2023, num = 29, official = 0, review = true))
        l.add(BProb(id = "e23_30", topic = "trig", level = 3, text = "En el triángulo ABC, se traza la mediana BM. Halle x.", opts = listOf("25°", "30°", "15°", "10°"), vals = listOf("25", "30", "15", "10"), correct = 2, check = "45-acos(1/2)/2*180/pi", steps = listOf("En la figura, el ángulo exterior en B entre la prolongación de AB y BC mide 45°, así que ∠ABC = 135°. Además ∠MBC = α, ∠BAM = α y ∠BMA = 45°.", "En el triángulo BMC: ∠BMC = 180° − 45° = 135°, así que x = 180° − 135° − α = 45° − α.", "En el triángulo ABM: ∠ABM = 135° − α. Ley de senos: AM = BM·sen(135° − α)/sen α.", "En el triángulo BMC: MC = BM·sen α/sen(45° − α).", "Como AM = MC: sen(135° − α)·sen(45° − α) = sen² α. Además sen(135° − α) = sen(45° + α), y el producto vale cos 2α/2. Queda cos 2α/2 = (1 − cos 2α)/2, es decir cos 2α = 1/2.", "Entonces 2α = 60°, α = 30° y x = 45° − 30° = 15°."), fig = "x23_30", theory = "Ley de senos: en un triángulo, cada lado dividido entre el seno del ángulo opuesto da lo mismo. Identidad: sen(45° + α)·sen(45° − α) = cos 2α / 2.", idea = "La mediana hace AM = MC. Se escribe cada mitad con la ley de senos usando el lado común BM.", mistake = "Responder el valor de α, 30°, que es la alternativa B, en lugar de x.", verify = "Con α = 30°: el triángulo ABM tiene ángulos 30°, 105° y 45°, y el BMC tiene 30°, 135° y 15°. Por ley de senos, AM/BM = sen 105°/sen 30° y MC/BM = sen 30°/sen 15°, y ambos valen 1,932.", trap = "acos(1/2)/2*180/pi", src = "oficial", year = 2023, num = 30, trapOpt = 1, official = 2))
        l.add(BProb(id = "e24_01", topic = "frac", level = 1, text = "Resuelve la siguiente operación:\n§pi-1/2\nRecuerda que: π = 3,141592653 …\nSegún el resultado de esta operación, ¿cuál de las siguientes afirmaciones es correcta?", opts = listOf("El resultado es igual a 2,641 cuando se aproxima a las milésimas.", "El resultado es igual a 2,65 cuando se aproxima a las centésimas.", "El resultado es igual a 2,642 cuando se aproxima a las milésimas.", "El resultado es igual a 2,64 cuando se aproxima a las décimas."), vals = listOf("round(evalf(pi-1/2,20)*1000)==2641", "round(evalf(pi-1/2,20)*100)==265", "round(evalf(pi-1/2,20)*1000)==2642", "round(evalf(pi-1/2,20)*10)==264"), correct = 2, check = "true", steps = listOf("π − 1/2 = 3,141592653… − 0,5 = 2,641592653…", "A las milésimas se conservan tres decimales, 2,641, y la cifra siguiente es 5. Entonces se sube: 2,642.", "A las centésimas: 2,64 y la cifra siguiente es 1. Queda 2,64, no 2,65.", "A las décimas: 2,6 y la cifra siguiente es 4. Queda 2,6, no 2,64.", "La única afirmación correcta es la C."), theory = "Para aproximar a una cifra se mira la cifra siguiente: si es 5 o más, la última cifra que se conserva sube en 1; si es menor que 5, se queda igual.", idea = "Primero se calcula π − 1/2 con suficientes decimales y luego se revisa cada aproximación.", mistake = "Cortar los decimales sin redondear: 2,641, que es la alternativa A.", verify = "2,642 − 2,641592… = 0,000407…, que es menor que media milésima. 2,642 es la milésima más cercana.", src = "oficial", year = 2024, num = 1, official = 2))
        l.add(BProb(id = "e24_02", topic = "arit", level = 1, text = "La luz, que la ciencia define como onda y partícula a la vez, recorre una distancia de 9 000 × 10⁹ metros a una velocidad de 300 × 10⁶ metros por segundo, ¿cuál es el tiempo transcurrido en segundos expresado en notación científica?\nRecuerda que: velocidad = distancia / tiempo", opts = listOf("3 × 10⁴", "30 × 10³", "6 × 10⁴", "30 × 10⁻³"), vals = listOf("9000*10^9/(300*10^6)==3*10^4 and 3>=1 and 3<10", "9000*10^9/(300*10^6)==30*10^3 and 30>=1 and 30<10", "9000*10^9/(300*10^6)==6*10^4 and 6>=1 and 6<10", "9000*10^9/(300*10^6)==30*10^(-3) and 30>=1 and 30<10"), correct = 0, check = "true", steps = listOf("Despejamos: tiempo = distancia ÷ velocidad = (9 000 × 10⁹) ÷ (300 × 10⁶).", "Dividimos los números: 9 000 ÷ 300 = 30. Dividimos las potencias: 10⁹ ÷ 10⁶ = 10³. Queda 30 × 10³ segundos.", "30 no está entre 1 y 10. Escribimos 30 = 3 × 10, así que 30 × 10³ = 3 × 10⁴ segundos."), theory = "Un número está en notación científica cuando se escribe como a × 10ⁿ con 1 ≤ a < 10. Para dividir potencias de la misma base se restan los exponentes.", idea = "Se despeja el tiempo: tiempo = distancia / velocidad. Luego se ajusta el resultado a notación científica.", mistake = "Quedarse con 30 × 10³, alternativa B. Tiene el valor correcto pero no está en notación científica porque 30 no es menor que 10.", verify = "3 × 10⁴ = 30 000 s y 300 × 10⁶ m/s por 30 000 s da 9 × 10¹² m, que es 9 000 × 10⁹ m.", src = "oficial", year = 2024, num = 2, official = 0))
    }
    private fun p4(l: MutableList<BProb>) {
        l.add(BProb(id = "e24_03", topic = "ecu", level = 1, text = "Dada la ecuación:\n§x^2+80=21*x\nHalla el menor valor de \"x\".", opts = listOf("–16", "– 5", "4", "5"), vals = listOf("-16", "-5", "4", "5"), correct = 3, check = "min(solve(x^2+80=21*x,x))", steps = listOf("Igualamos a cero: x² − 21x + 80 = 0.", "Buscamos dos números que multiplicados den 80 y sumados den 21: son 5 y 16.", "Factorizamos: (x − 5)(x − 16) = 0, así que x = 5 o x = 16.", "El menor valor es 5."), theory = "Una ecuación de segundo grado se iguala a cero y se factoriza buscando dos números que multiplicados den el término independiente y sumados den el coeficiente de x.", idea = "Se pasa todo a un lado: x² − 21x + 80 = 0.", mistake = "Equivocarse con los signos al factorizar y obtener −5 y −16, y elegir la menor: −16, alternativa A.", verify = "5² + 80 = 105 = 21·5 y 16² + 80 = 336 = 21·16. Ambas raíces cumplen.", trap = "-max(solve(x^2+80=21*x,x))", src = "oficial", year = 2024, num = 3, trapOpt = 0, official = 3))
        l.add(BProb(id = "e24_04", topic = "porc", level = 1, text = "Elsa presta 500 soles a su amigo Carlos, con la condición de que él le devuelva el dinero prestado con un interés del 8 % mensual. Después de 2 meses, Carlos devuelve el dinero que prestó más el interés acordado por este préstamo.\nPara esta situación, ¿cuánto dinero en total devolvió Carlos a Elsa por el préstamo?\nRecuerda que: Interés = Capital incial × Tasa de interés × Tiempo", opts = listOf("S/ 40", "S/ 80", "S/ 516", "S/ 580"), vals = listOf("40", "80", "516", "580"), correct = 3, check = "500+500*8/100*2", steps = listOf("Capital 500, tasa 8 % mensual = 0,08 y tiempo 2 meses.", "Interés: 500·0,08·2 = 80 soles.", "Total devuelto: 500 + 80 = 580 soles."), note = "En el recuadro del examen dice Capital incial; se respeta tal como está escrito.", theory = "Interés simple: I = C·r·t, con la tasa y el tiempo en la misma unidad. El monto que se devuelve es capital más interés.", idea = "Lo que se devuelve en total es el capital más el interés.", mistake = "Responder solo el interés, S/ 80, alternativa B. La pregunta pide el total devuelto.", verify = "Cada mes el interés es 500·0,08 = 40. En dos meses, 80. Más el préstamo, 580.", trap = "500*8/100*2", src = "oficial", year = 2024, num = 4, trapOpt = 1, official = 3))
        l.add(BProb(id = "e24_05", topic = "suc", level = 1, text = "Un cuadrado se divide en dos partes iguales y esta acción se repite en cada una de las partes divididas, y así sucesivamente. En las figuras se presentan las tres primeras acciones:\n¿En cuántas partes se dividirá el cuadrado cuando se realice la acción 8?", opts = listOf("8", "16", "256", "512"), vals = listOf("8", "16", "256", "512"), correct = 2, check = "2^8", steps = listOf("Acción 1: el cuadrado queda en 2 partes.", "Acción 2: cada una de las 2 partes se divide en dos: 4 partes. Acción 3: 8 partes.", "Las partes forman 2, 4, 8, …, es decir 2ⁿ después de la acción n.", "En la acción 8: 2⁸ = 256 partes."), fig = "x24_05", theory = "Si en cada paso cada parte se divide en dos, el número de partes se multiplica por 2. Después de n pasos hay 2ⁿ partes.", idea = "Cada acción duplica la cantidad de partes.", mistake = "Contar una acción de más y calcular 2⁹ = 512, alternativa D.", verify = "2⁸ = 2·2·2·2·2·2·2·2 = 256. Con la acción 3 la fórmula da 2³ = 8, como en la figura.", trap = "2^(8+1)", src = "oficial", year = 2024, num = 5, trapOpt = 3, official = 2))
        l.add(BProb(id = "e24_06", topic = "geo", level = 1, text = "En una institución educativa se desea cambiar el tablero de las mesas de trabajo de forma cuadrada a un tablero que tenga un diseño más funcional para que los estudiantes puedan formar grupos fácilmente.\nSegún esta información, ¿qué cuadrilátero representa la forma que debe tener el tablero de las mesas, sabiendo que las diagonales del tablero son iguales?", opts = listOf("Trapecio rectángulo", "Trapecio isósceles", "Trapecio escaleno", "Trapezoide"), vals = emptyList(), correct = 1, check = "", steps = listOf("En la vista de arriba el tablero tiene dos lados paralelos: es un trapecio, no un trapezoide.", "En un trapecio isósceles los lados no paralelos son iguales y la figura es simétrica respecto a la recta que une los puntos medios de las bases. Por esa simetría, cada diagonal es la imagen de la otra y miden lo mismo.", "En el trapecio rectángulo y en el escaleno no hay esa simetría y las diagonales son distintas.", "La forma es un trapecio isósceles."), fig = "x24_06", theory = "Un trapecio tiene un par de lados paralelos. Es isósceles cuando sus lados no paralelos son iguales; en ese caso es simétrico y sus diagonales miden lo mismo.", idea = "La vista de arriba muestra un trapecio, y la condición de diagonales iguales solo la cumple el isósceles.", mistake = "Elegir trapezoide por el nombre parecido. Un trapezoide no tiene lados paralelos.", verify = "Ejemplo: bases 4 y 2 con altura 2, centradas. Las diagonales unen (0; 0) con (3; 2) y (4; 0) con (1; 2), y ambas miden √13.", src = "oficial", year = 2024, num = 6, official = 1))
        l.add(BProb(id = "e24_07", topic = "prob", level = 1, text = "Martha lanza una moneda al aire tres veces, ¿cuántas formas diferentes tiene Martha en total para obtener al menos una cara en los tres lanzamientos?", opts = listOf("1", "3", "7", "6"), vals = listOf("1", "3", "7", "6"), correct = 2, check = "2^3-1", steps = listOf("Total de resultados: 2·2·2 = 8.", "Sin ninguna cara hay un solo resultado: sello, sello, sello.", "Con al menos una cara: 8 − 1 = 7 formas."), theory = "Principio de multiplicación: si cada lanzamiento tiene 2 resultados, tres lanzamientos tienen 2³ resultados. Al menos uno es todo menos ninguno.", idea = "Es más fácil contar el único caso sin caras y restarlo del total.", mistake = "Contar solo los casos con exactamente una cara: 3, alternativa B.", verify = "Contando directo: exactamente una cara, 3 formas; dos caras, 3; tres caras, 1. Total 3 + 3 + 1 = 7.", trap = "binomial(3,1)", src = "oficial", year = 2024, num = 7, trapOpt = 1, official = 2))
        l.add(BProb(id = "e24_08", topic = "alg", level = 3, text = "Abel y Benjamín juegan con fichas con la condición de que el perdedor de cada partida le entregará al otro el cuadrado de la cantidad de fichas que este tiene. En un determinado momento del juego, Abel y Benjamín tienen 2 y 270 fichas cada uno respectivamente; aun así, deciden seguir jugando. Abel ganó las tres partidas siguientes y el juego terminó.\nRespecto a la cantidad total de fichas que Abel tuvo al final del juego, ¿cuál de las siguientes expresiones representa a esta cantidad?", opts = listOf("2⁴ fichas", "2⁶ fichas", "2⁸ fichas", "2¹⁶ fichas"), vals = listOf("2^4", "2^6", "2^8", "2^16"), correct = 2, check = "((2^2)^2)^2", steps = listOf("Abel empieza con 2 = 2¹ fichas.", "Primera victoria: 2² = 4 fichas.", "Segunda victoria: 4² = (2²)² = 2⁴ = 16 fichas.", "Tercera victoria: 16² = (2⁴)² = 2⁸ = 256 fichas.", "Benjamín entrega 2 + 12 + 240 = 254 de sus 270 fichas, así que sí le alcanzan."), note = "Si Abel recibiera el cuadrado de lo que tiene además de lo que ya tenía, pasaría a 6, luego a 42 y necesitaría 1764 fichas más, que Benjamín no tiene. Por eso la única lectura posible es la de la clave: cada victoria deja a Abel con el cuadrado de su cantidad.", theory = "Potencia de una potencia: (aᵐ)ⁿ = aᵐ·ⁿ.", idea = "Como lo indica la clave oficial, cada victoria deja a Abel con el cuadrado de lo que tenía.", mistake = "Multiplicar los exponentes como si se sumaran: 2·3 = 6 y responder 2⁶, alternativa B.", verify = "2⁸ = 256 y Abel recibió 254 fichas además de las 2 iniciales: 2 + 254 = 256.", warn = "La redacción admite dos lecturas. Lee la nota de la solución.", trap = "2^(2*3)", src = "oficial", year = 2024, num = 8, trapOpt = 1, official = 2, review = true))
        l.add(BProb(id = "e24_09", topic = "ecu", level = 1, text = "Juan organiza una parrillada para apoyar a la compañía de bomberos de su ciudad. Él estima que el costo fijo de alquiler de local, contrato de cocineros y personal de apoyo asciende a S/ 1 400 en total y el costo de preparar cada parrillada es de S/ 8.\nDetermina la función que representa el monto total (M) de dinero que se gastará en la parrillada, donde \"x\" representa la cantidad de parrilladas.", opts = listOf("§M(x)=1400", "§M(x)=8*x", "§M(x)=1400+8*x", "§M(x)=1400+x"), vals = listOf("1400", "8*x", "1400+8*x", "1400+x"), correct = 2, check = "1400+8*x", steps = listOf("El costo fijo es S/ 1 400, sin importar cuántas parrilladas se preparen.", "Cada parrillada cuesta S/ 8, así que x parrilladas cuestan 8x.", "El monto total es la suma: M(x) = 1400 + 8x."), theory = "Costo total = costo fijo + costo por unidad × cantidad de unidades. El costo fijo no depende de cuántas unidades se preparen.", idea = "Hay una parte que no cambia, 1400, y otra que crece 8 soles por cada parrillada.", mistake = "Olvidar el costo fijo y escribir M(x) = 8x, alternativa B.", verify = "Con 10 parrilladas: M(10) = 1400 + 80 = 1480, que es el fijo más 10 veces 8.", trap = "8*x", src = "oficial", year = 2024, num = 9, trapOpt = 1, official = 2))
        l.add(BProb(id = "e24_10", topic = "prop", level = 1, text = "Cuatro estudiantes de un centro educativo entrenan en la pista atlética del Estadio Nacional con miras a un campeonato escolar de atletismo que se aproxima. En la siguiente tabla se muestran los tiempos por tramos (distancia recorrida) que hacen estos estudiantes en parte de su entrenamiento.\n[tabla]\nSegún la información de esta tabla, ¿qué estudiante tiene la mayor rapidez durante su entrenamiento?\nRecuerda que: rapidez = distancia / tiempo", opts = listOf("Cristhian", "Lucía", "Sofía", "Raúl"), vals = listOf("15000/(45*60)", "1200/(3*60+20)", "4200/(15*60)", "10800/2400"), correct = 1, check = "max(15000/(45*60),1200/(3*60+20),4200/(15*60),10800/2400)", steps = listOf("Cristhian: 45 minutos = 2 700 s. Rapidez 15 000 ÷ 2 700 ≈ 5,56 m/s.", "Lucía: 3 min 20 s = 200 s. Rapidez 1 200 ÷ 200 = 6 m/s.", "Sofía: 15 minutos = 900 s. Rapidez 4 200 ÷ 900 ≈ 4,67 m/s.", "Raúl: 2 400 s. Rapidez 10 800 ÷ 2 400 = 4,5 m/s.", "La mayor rapidez es la de Lucía."), theory = "Para comparar rapideces hay que usar las mismas unidades. Rapidez = distancia ÷ tiempo.", idea = "Los tiempos están en unidades distintas: primero se pasan todos a segundos.", mistake = "Elegir a quien recorre más distancia, Cristhian, sin dividir entre el tiempo.", verify = "En metros por minuto: Lucía 360, Cristhian 333,3, Sofía 280 y Raúl 270. El orden es el mismo.", src = "oficial", table = listOf(listOf("Atleta", "Distancia recorrida", "Tiempo"), listOf("Cristhian", "15 000 m", "45 minutos"), listOf("Lucía", "1 200 m", "3 minutos 20 segundos"), listOf("Sofía", "4 200 m", "15 minutos"), listOf("Raúl", "10 800 m", "2 400 segundos")), year = 2024, num = 10, official = 1))
    }
    private fun p5(l: MutableList<BProb>) {
        l.add(BProb(id = "e24_11", topic = "frac", level = 1, text = "María debe preparar una solución de alcohol y agua en un envase para que sus hijos se desinfecten las manos al ingresar a su casa. Según las indicaciones de la posta médica de su comunidad, ella primero debe llenar con alcohol una parte de este envase, hasta el nivel señalado, tal como se muestra en la figura. Lo que falta llenar del envase, María lo completa con agua.\nSegún esta información, ¿cuál de las siguientes afirmaciones es correcta?", opts = listOf("La razón entre la cantidad de alcohol y la cantidad de agua en el envase es 4/10.", "La cantidad de alcohol es 5/7 de la capacidad total del envase.", "La cantidad de agua es 5/2 de la capacidad total del envase.", "La razón entre la cantidad de agua y la cantidad de alcohol en el envase es 2/7."), vals = listOf("1000/400==4/10", "1000/1400==5/7", "400/1400==5/2", "400/1000==2/7"), correct = 1, check = "true", steps = listOf("De la figura: alcohol 1 000 ml y agua 400 ml. Total 1 400 ml.", "A: alcohol entre agua es 1000/400 = 5/2, no 4/10.", "B: alcohol entre total es 1000/1400 = 5/7. Es correcta.", "C: agua entre total es 400/1400 = 2/7, no 5/2.", "D: agua entre alcohol es 400/1000 = 2/5, no 2/7."), fig = "x24_11", theory = "Una razón compara dos cantidades dividiéndolas en el orden que se nombran. La fracción de un total es la parte dividida entre el total.", idea = "La capacidad total es alcohol más agua: 1000 + 400 = 1400 ml.", mistake = "Invertir el orden de la razón. Así sale 4/10 en lugar de 10/4, como en la alternativa A.", verify = "5/7 + 2/7 = 1: el alcohol y el agua juntos llenan el envase.", src = "oficial", year = 2024, num = 11, official = 1))
        l.add(BProb(id = "e24_12", topic = "ineq", level = 1, text = "Dados los siguientes intervalos de números reales:\nA = [− 1/2 ; 1/2]   ;   B = ]− 1/4 ; 1/4[\n¿Cuál es la intersección entre los intervalos A y B?", opts = listOf("[− 1/4 ; 1/4]", "[− 1/2 ; 1/4[", "]− 1/4 ; 1/4[", "]− 1/4 ; 1/2]"), vals = listOf("[-1/4,1/4,1,1]", "[-1/2,1/4,1,0]", "[-1/4,1/4,0,0]", "[-1/4,1/2,0,1]"), correct = 2, check = "[max(-1/2,-1/4),min(1/2,1/4),0,0]", steps = listOf("A va de −1/2 a 1/2 con extremos incluidos. B va de −1/4 a 1/4 con extremos excluidos.", "Como −1/2 < −1/4 y 1/4 < 1/2, todo B está dentro de A.", "La intersección es B, con sus extremos abiertos: ]−1/4 ; 1/4[."), theory = "La intersección de dos intervalos son los números que están en los dos a la vez. Un corchete hacia adentro incluye el extremo; hacia afuera lo excluye.", idea = "B está completamente dentro de A, así que la intersección es el mismo B.", mistake = "Copiar los extremos de B pero cerrarlos con corchetes de A: [−1/4 ; 1/4], alternativa A.", verify = "El número 1/4 no está en B, así que no puede estar en la intersección. El 0 sí está en ambos.", trap = "[-1/4,1/4,1,1]", src = "oficial", year = 2024, num = 12, trapOpt = 0, official = 2))
        l.add(BProb(id = "e24_13", topic = "prop", level = 2, text = "En una granja avícola se organiza los corrales teniendo en cuenta la edad de las aves. Para distribuir la comida para estas aves, se utilizan bolsas de igual peso. En la siguiente tabla, se muestra la cantidad de aves de una misma edad que hay en un sector de corrales y el número de días que les dura una bolsa de comida.\n[tabla]\nDe las opciones que se muestran, ¿cuál es la expresión que permite calcular el número de días que durará la bolsa de comida para un corral de 25 aves?", opts = listOf("§50+4=25+x", "§40-5=25-x", "§100/2=25/x", "(20)(10) = (25)(x)"), vals = listOf("solve(50+4=25+x,x)[0]", "solve(40-5=25-x,x)[0]", "solve(100/2=25/x,x)[0]", "solve(20*10=25*x,x)[0]"), correct = 3, check = "20*10/25", steps = listOf("Multiplicamos aves por días en cada fila: 20·10 = 200, 40·5 = 200, 50·4 = 200 y 100·2 = 200.", "El producto es constante, así que las magnitudes son inversamente proporcionales.", "Para 25 aves: 25·x = 200, que se escribe (20)(10) = (25)(x).", "De ahí x = 8 días."), theory = "Dos magnitudes son inversamente proporcionales cuando su producto es constante: si una se duplica, la otra se reduce a la mitad.", idea = "Con más aves la bolsa dura menos días. En la tabla, aves por días siempre da 200.", mistake = "Plantear una proporción directa como 100/2 = 25/x. Eso da x = 1/2 día, que no tiene sentido.", verify = "25 aves por 8 días = 200, igual que en las demás filas.", src = "oficial", table = listOf(listOf("Corral", "N° de aves en el corral", "N° de días que dura la comida"), listOf("1", "20", "10"), listOf("2", "25", "x"), listOf("3", "40", "5"), listOf("4", "50", "4"), listOf("…", "…", "…"), listOf("10", "100", "2")), year = 2024, num = 13, official = 3))
        l.add(BProb(id = "e24_14", topic = "porc", level = 2, text = "Andrea desea comprar una olla arrocera por lo que visita dos tiendas en las que encuentra la olla que quiere con un mismo precio de etiqueta (precio sin descuento), pero con las ofertas que se muestran a continuación:\n[tabla]\nSegún la información mostrada para estas ofertas, ¿cuál de las siguientes afirmaciones es correcta para la compra de Andrea?", opts = listOf("Le conviene la oferta, ya sea de la tienda 1 o de la tienda 2, porque el descuento total en cada una de estas es el mismo (40 % + 10 % = 30 % + 20 %).", "Le conviene comprar en la tienda 2 porque el descuento total en la tienda 1 equivale al 54 % del precio de etiqueta y en la tienda 2 el descuento total equivale al 56 % del precio de etiqueta.", "Le conviene comprar en la tienda 1 porque el descuento total en esta tienda equivale al 46 % del precio de etiqueta y en la tienda 2 el descuento total equivale al 44 % del precio de etiqueta.", "Le conviene comprar en la tienda 2 porque el descuento total obtenido en la tienda 1 equivale a 40 %(10 %) = 4 % y en la tienda 2 equivale a 30 %(20 %) = 6 %."), vals = listOf("1-60/100*90/100==1-70/100*80/100", "1-60/100*90/100==54/100 and 1-70/100*80/100==56/100", "1-60/100*90/100==46/100 and 1-70/100*80/100==44/100", "1-60/100*90/100==4/100 and 1-70/100*80/100==6/100"), correct = 2, check = "true", steps = listOf("Tienda 1: con 40 % de descuento se paga 60 %, y con 10 % adicional se paga 90 % de eso. Se paga 0,60·0,90 = 0,54, es decir 54 %. El descuento total es 46 %.", "Tienda 2: se paga 0,70·0,80 = 0,56, es decir 56 %. El descuento total es 44 %.", "En la tienda 1 se paga menos, así que le conviene la tienda 1, con descuentos de 46 % y 44 %."), note = "En el examen las ofertas aparecen como dos carteles; aquí sus datos están en la tabla.", theory = "Descuentos sucesivos: cada descuento se aplica sobre el precio ya rebajado, así que se multiplican los porcentajes que se pagan; no se suman los descuentos.", idea = "Se calcula qué fracción del precio de etiqueta se paga en cada tienda.", mistake = "Confundir lo que se paga con lo que se descuenta: 54 % y 56 % son lo que se paga, como dice la alternativa B.", verify = "Con una olla de S/ 100: en la tienda 1 paga 60 y luego 54; en la tienda 2 paga 70 y luego 56. Ahorra S/ 2 en la tienda 1.", src = "oficial", table = listOf(listOf("", "Oferta en tienda 1", "Oferta en tienda 2"), listOf("Descuento en todo electrodomésticos", "40 %", "30 %"), listOf("Descuento adicional pagando en efectivo", "+10 %", "+20 %")), year = 2024, num = 14, official = 2))
        l.add(BProb(id = "e24_15", topic = "est", level = 2, text = "La gráfica muestra cómo se comporta la temperatura promedio diaria durante el mes de febrero en la ciudad de Arequipa.\nSegún la gráfica, ¿cuál de las siguientes conclusiones es correcta?", opts = listOf("La temperatura en el día 21 fue el doble que la del día 11.", "La temperatura más baja se registró al inicio de mes.", "En el día 23, la temperatura fue aproximadamente 30 °C.", "Durante el mes de febrero en cuatro días la temperatura fue 20 °C."), vals = emptyList(), correct = 3, check = "", steps = listOf("A: el día 21 la temperatura es cerca de 31 °C y el día 11 cerca de 18 °C. El doble de 18 es 36, así que A es falsa.", "B: la temperatura más baja, cerca de 6 °C, está al final del mes, el día 28. B es falsa.", "C: el día 23 la curva marca cerca de 31 °C, un grado por encima de la línea de 30. C no es la conclusión que se lee en la gráfica.", "D: la recta de 20 °C corta la curva en cuatro puntos: cerca del día 3, del día 7, entre los días 12 y 13, y cerca del día 26. D es la correcta."), fig = "x24_15", note = "La curva se redibujó midiendo la gráfica original punto por punto.", theory = "Leer una gráfica de línea: para un día se sube desde el eje horizontal hasta la curva y se lee el valor en el eje vertical. Los cortes con una recta horizontal indican cuántas veces se alcanza ese valor.", idea = "Se revisa cada afirmación con lecturas en la cuadrícula.", mistake = "Aceptar la C porque 31 °C se parece a 30 °C. Hay que elegir la conclusión que se cumple exactamente según la gráfica.", verify = "Recorriendo la curva: sube hasta 20 °C, pasa por encima, baja a 20, baja más, vuelve a subir a 20, llega a 32 y finalmente baja otra vez por 20. Son cuatro pasos por 20 °C.", src = "oficial", year = 2024, num = 15, official = 3))
        l.add(BProb(id = "e24_16", topic = "ecu", level = 1, text = "Un grupo de estudiantes recaudó la suma de S/ 3 360 para alquilar 16 buses que los transportará a un museo. Los buses que cuentan con aire acondicionado tienen un costo de alquiler de S/ 300 y los buses sin aire acondicionado, S/ 180. Este grupo alquilará una cierta cantidad de buses de ambos tipos. Para determinar estas cantidades, se plantea el siguiente sistema de ecuaciones:\n180x + 300y = 3360\nx + y = 16\nDonde:\n\"x\" representa la cantidad de buses sin aire acondicionado\n\"y\" representa la cantidad de buses con aire acondicionado\n¿Cuántos buses con aire acondicionado alquilará el grupo de estudiantes?", opts = listOf("12", "10", "4", "1"), vals = listOf("12", "10", "4", "1"), correct = 2, check = "linsolve([180*x+300*y=3360,x+y=16],[x,y])[1]", steps = listOf("De x + y = 16 despejamos x = 16 − y.", "Reemplazamos en la primera: 180(16 − y) + 300y = 3360.", "2880 − 180y + 300y = 3360, así que 120y = 480 y y = 4.", "Alquilarán 4 buses con aire acondicionado y 12 sin aire."), theory = "Un sistema de dos ecuaciones se resuelve por sustitución: se despeja una incógnita en una ecuación y se reemplaza en la otra.", idea = "De la segunda ecuación, x = 16 − y. Así queda una sola incógnita.", mistake = "Responder los buses sin aire acondicionado, x = 12, alternativa A.", verify = "12·180 + 4·300 = 2160 + 1200 = 3360 y 12 + 4 = 16.", trap = "linsolve([180*x+300*y=3360,x+y=16],[x,y])[0]", src = "oficial", year = 2024, num = 16, trapOpt = 0, official = 2))
        l.add(BProb(id = "e24_17", topic = "trig", level = 3, text = "Un ingeniero está elaborando mapas de una región montañosa utilizando un teodolito de 1,8 metros de altura. Desde una posición A, él mide un ángulo de elevación de 64° hacia la cima de una montaña. Luego, se desplaza 140 metros hacia esta montaña hasta llegar a la posición B, donde mide un ángulo de elevación de 76° hacia su cima.\nConsidera: cot(64°) = 0,5  y  tan(76°) = 4\n¿Cuál es la altura de la montaña?", opts = listOf("70 metros", "71,80 metros", "560 metros", "561,8 metros"), vals = listOf("70", "359/5", "560", "2809/5"), correct = 3, check = "solve(h/2-h/4=140,h)[0]+9/5", steps = listOf("Sea h la altura de la cima sobre el teodolito. Desde A la distancia horizontal es h·cot 64° = 0,5h.", "Desde B: cot 76° = 1/tan 76° = 1/4, así que la distancia es h/4.", "Diferencia de distancias: 0,5h − 0,25h = 140, es decir 0,25h = 140 y h = 560 m.", "La altura de la montaña suma la altura del teodolito: 560 + 1,8 = 561,8 m."), fig = "x24_17", theory = "En un triángulo rectángulo, la cotangente de un ángulo agudo es cateto adyacente entre cateto opuesto. La distancia horizontal a la cima es la altura por la cotangente del ángulo de elevación.", idea = "Las distancias horizontales desde A y desde B difieren en 140 m. La altura se mide desde los ojos del teodolito y luego se suman sus 1,8 m.", mistake = "Olvidar sumar la altura del teodolito y responder 560 m, alternativa C.", verify = "Desde A la distancia es 280 m y desde B es 140 m; la diferencia es 140 m, como dice el enunciado.", trap = "solve(h/2-h/4=140,h)[0]", src = "oficial", year = 2024, num = 17, trapOpt = 2, official = 3))
        l.add(BProb(id = "e24_18", topic = "geo", level = 2, text = "Una constructora quiere reforzar las llantas de sus carretillas para que sean más resistentes. Una de hacerlo consiste en colocar varillas del mismo tamaño, utilizando como referencia algunas cuerdas de la circunferencia que rodea el aro de la llanta formando un polígono, tal como se muestra en la figura, donde \"θ\" es el ángulo central del sector circular AOB.\nSegún esta información, ¿cuál de las siguientes afirmaciones es correcta?", opts = listOf("Si la varilla tiene la misma longitud que el radio, las varillas forman un pentágono.", "Si el ángulo θ = 30°, las varillas forman un hexágono.", "Si el ángulo α = 135°, las varillas forman un octógono.", "Si el ángulo α = 72°, las varillas forman un pentágono."), vals = listOf("360/60==5", "360/30==6", "360/(180-135)==8", "360/(180-72)==5"), correct = 2, check = "true", steps = listOf("A: cuerda igual al radio da ángulo central 60°, y 360 ÷ 60 = 6 lados. Es hexágono, no pentágono.", "B: θ = 30° da 360 ÷ 30 = 12 lados, no 6.", "C: el ángulo interior α = 135° corresponde a un ángulo central de 180° − 135° = 45°, y 360 ÷ 45 = 8 lados. Es un octógono. Correcta.", "D: el ángulo interior de un pentágono regular es 108°, no 72°. 72° es su ángulo central."), fig = "x24_18", note = "En el original dice Una de hacerlo; se respeta tal como está escrito.", theory = "En un polígono regular de n lados inscrito, el ángulo central mide 360°/n y el ángulo interior mide 180° − 360°/n. Si una cuerda mide igual que el radio, el triángulo central es equilátero y el ángulo central es 60°.", idea = "Las varillas son lados de un polígono regular. Con el ángulo central o el interior se halla el número de lados.", mistake = "Confundir el ángulo central con el interior. En el pentágono el central mide 72°, por eso la alternativa D parece correcta.", verify = "Octógono regular: ángulo interior 180°·6/8 = 135°.", src = "oficial", year = 2024, num = 18, official = 2))
    }
    private fun p6(l: MutableList<BProb>) {
        l.add(BProb(id = "e24_19", topic = "prob", level = 2, text = "Ernesto participa en un juego de la feria de su ciudad, en el cual se ofrece que todos reciben un premio. El juego consiste en sacar una bola de billar (numeradas del 1 al 15) de una canasta y escoger solo un premio de la siguiente tabla, según el número indicado en la bola de billar. Cada vez que Ernesto juega debe pagar S/ 5 por el ticket.\n[tabla]\nSegún esta información, ¿cuál de las siguientes afirmaciones es falsa?", opts = listOf("Es seguro que Ernesto reciba al menos S/ 20 si juega 10 veces.", "Es posible que Ernesto pierda S/ 3 en una jugada.", "Es imposible que Ernesto gane S/ 1 000 en una jugada.", "Es seguro que Ernesto reclame S/ 1 de premio como mínimo en una jugada."), vals = listOf("10*min(seq(max(when(irem(k,2)==0 and k<8,1,0),when(irem(k,2)==1 and k>7,1,0),when(irem(k,2)==0 and k>6,2,0),when(irem(k,2)==1 and k<9,8,0),when(irem(k,2)==0 and k>14,1000,0)),k,1,15))>=20", "member(2,seq(max(when(irem(k,2)==0 and k<8,1,0),when(irem(k,2)==1 and k>7,1,0),when(irem(k,2)==0 and k>6,2,0),when(irem(k,2)==1 and k<9,8,0),when(irem(k,2)==0 and k>14,1000,0)),k,1,15))>0", "max(seq(max(when(irem(k,2)==0 and k<8,1,0),when(irem(k,2)==1 and k>7,1,0),when(irem(k,2)==0 and k>6,2,0),when(irem(k,2)==1 and k<9,8,0),when(irem(k,2)==0 and k>14,1000,0)),k,1,15))<1000", "min(seq(max(when(irem(k,2)==0 and k<8,1,0),when(irem(k,2)==1 and k>7,1,0),when(irem(k,2)==0 and k>6,2,0),when(irem(k,2)==1 and k<9,8,0),when(irem(k,2)==0 and k>14,1000,0)),k,1,15))>=1"), correct = 0, check = "false", steps = listOf("Bolas 2, 4 y 6: par menor que 8, premio S/ 1.", "Bolas 8, 10, 12 y 14: par mayor que 6, premio S/ 2, que es mejor que S/ 1.", "Bolas 1, 3, 5 y 7: impar menor que 9, premio S/ 8. Bolas 9, 11, 13 y 15: impar mayor que 7, premio S/ 1.", "No hay bola par mayor que 14, así que el premio de S/ 1 000 nunca sale. C es verdadera.", "Con premio S/ 2 pierde 5 − 2 = 3 soles: B es verdadera. Siempre recibe al menos S/ 1: D es verdadera.", "A: en el peor caso recibe S/ 1 en cada jugada, es decir S/ 10 en 10 jugadas, no S/ 20. A es falsa."), theory = "Un suceso es seguro si ocurre en todos los casos, posible si ocurre en al menos uno e imposible si no ocurre en ninguno.", idea = "Para cada bola se ve el mejor premio que puede escoger; luego se revisa el peor caso y el mejor caso.", mistake = "Pensar que la C es falsa porque el premio de S/ 1 000 aparece en la tabla. Ninguna bola del 1 al 15 es par y mayor que 14.", verify = "Si las 10 bolas fueran por ejemplo la 2, el premio total sería 10·1 = S/ 10, menor que S/ 20.", src = "oficial", table = listOf(listOf("Resultado", "Premio"), listOf("Obtener un número par menor que 8 o impar mayor que 7", "S/ 1,00"), listOf("Obtener un número par mayor que 6", "S/ 2,00"), listOf("Obtener un número impar menor de 9", "S/ 8,00"), listOf("Obtener un número par mayor a 14", "S/ 1 000,00")), year = 2024, num = 19, official = 0))
        l.add(BProb(id = "e24_20", topic = "geo", level = 2, text = "Tres empresas pertenecientes a un consorcio se unen para construir un local de recreación para las horas de descanso de sus trabajadores y que se encuentre a la misma distancia de sus edificios, ubicados en los puntos A, B y C, tal como se muestra en la figura. Si la distancia entre los edificios A y B es 72 metros, la distancia entre B y C es 96 metros, y la distancia entre A y C es de 120 metros, ¿a qué distancia se encontrará el local de recreación de los tres edificios?", opts = listOf("36 metros", "40 metros", "48 metros", "60 metros"), vals = listOf("36", "40", "48", "60"), correct = 3, check = "120/2", steps = listOf("72² + 96² = 5184 + 9216 = 14 400 = 120². Por el recíproco de Pitágoras, el triángulo es rectángulo en B y la hipotenusa es AC = 120.", "El local debe estar a igual distancia de A, B y C: es el circuncentro.", "En el triángulo rectángulo el circuncentro es el punto medio de la hipotenusa, y la distancia a los vértices es la mitad: 120 ÷ 2 = 60 m."), fig = "x24_20", theory = "El punto que está a la misma distancia de los tres vértices de un triángulo es el circuncentro. En un triángulo rectángulo, el circuncentro es el punto medio de la hipotenusa.", idea = "Los lados 72, 96 y 120 forman un triángulo rectángulo.", mistake = "Tomar la mitad de otro lado que no es la hipotenusa, por ejemplo 96 ÷ 2 = 48, alternativa C.", verify = "Los lados son 24 veces 3, 4 y 5. El radio del círculo que pasa por los tres puntos es la mitad de la hipotenusa: 60.", trap = "96/2", src = "oficial", year = 2024, num = 20, trapOpt = 2, official = 3))
        l.add(BProb(id = "e24_21", topic = "est", level = 2, text = "De las estadísticas mostradas por OSINERGMIN en su libro \"La industria del gas natural en el Perú\" se tiene la evolución de la producción de gas natural en el periodo 2004 – 2013 en MMPCD (millones de pies cúbicos diarios).\nSegún esta gráfica, ¿cuál de las siguientes conclusiones es correcta?", opts = listOf("El porcentaje del gas de Camisea respecto al Total País se incrementa a más del doble del 2004 al 2005.", "El mayor crecimiento anual en la producción del gas Total País se da al pasar del año 2010 al 2011.", "El mayor crecimiento anual en la producción del gas de Camisea se da al pasar del año 2012 al 2013.", "El crecimiento de producción del año 2009 respecto al 2006 del gas de Camisea y de la producción del gas Total País son iguales."), vals = listOf("50/23>2", "1033-699==max(145-83,172-145,259-172,328-259,336-328,699-336,1033-699,1144-1033,1180-1144)", "1139-1083==max(73-19,103-73,189-103,254-189,273-254,640-273,972-640,1083-972,1139-1083)", "273-103==336-172"), correct = 0, check = "true", steps = listOf("A: el porcentaje pasa de 23 % en 2004 a 50 % en 2005. El doble de 23 es 46, y 50 > 46. A es correcta.", "B: crecimientos del Total País: de 2009 a 2010 son 699 − 336 = 363, y de 2010 a 2011 son 1033 − 699 = 334. El mayor no es el de 2010 a 2011.", "C: de 2012 a 2013 Camisea crece 1139 − 1083 = 56, pero de 2009 a 2010 creció 640 − 273 = 367. C es falsa.", "D: de 2006 a 2009 Camisea crece 273 − 103 = 170 y el Total País 336 − 172 = 164. No son iguales."), fig = "x24_21", note = "La gráfica se redibujó con los valores impresos en el original: barras de Camisea y Total País y la línea del porcentaje.", theory = "Crecimiento anual es la diferencia entre la producción de un año y la del año anterior. Más del doble significa que el nuevo valor supera a dos veces el anterior.", idea = "Cada afirmación se comprueba con los números escritos en la gráfica.", mistake = "Mirar solo qué barras se ven más altas en lugar de restar. Así parece que el mayor salto es de 2010 a 2011, alternativa B.", verify = "Los crecimientos del Total País año a año son 62, 27, 87, 69, 8, 363, 334, 111 y 36. El mayor, 363, es de 2009 a 2010.", src = "oficial", year = 2024, num = 21, official = 0))
        l.add(BProb(id = "e24_22", topic = "geo", level = 3, text = "Un agricultor tiene un terreno triangular cuyos lados miden 300, 400 y 500 metros. Para dividir el terreno en dos regiones de igual área, se instala una valla metálica recta que inicia en el vértice opuesto al lado que mide 400 metros.\nPara esta situación, ¿cuál es la longitud de la valla metálica recta que se instalará?", opts = listOf("200 metros.", "300 metros.", "100√13 metros.", "50√73 metros."), vals = listOf("200", "300", "100*sqrt(13)", "50*sqrt(73)"), correct = 2, check = "sqrt(300^2+(400/2)^2)", steps = listOf("300² + 400² = 90 000 + 160 000 = 250 000 = 500². El triángulo es rectángulo, con catetos 300 y 400.", "El vértice opuesto al lado de 400 es el extremo del cateto de 300 que no está en el ángulo recto.", "La valla llega al punto medio del cateto de 400, que está a 200 m del ángulo recto.", "Se forma un triángulo rectángulo con catetos 300 y 200: valla = √(300² + 200²) = √130 000 = 100√13 m."), theory = "Una mediana va de un vértice al punto medio del lado opuesto y divide al triángulo en dos triángulos de igual área, porque tienen bases iguales y la misma altura.", idea = "La valla que parte el terreno en dos áreas iguales desde ese vértice es la mediana al lado de 400 m.", mistake = "Trazar la mediana al lado de 300 en lugar del de 400: √(400² + 150²) = 50√73, alternativa D.", verify = "100√13 ≈ 360,6 m, que está entre 300 y 500, como debe ser.", trap = "sqrt(400^2+(300/2)^2)", src = "oficial", year = 2024, num = 22, trapOpt = 3, official = 2))
        l.add(BProb(id = "e24_23", topic = "ecu", level = 1, text = "Seis hermanos van a repartirse una herencia, pero dos de ellos renunciaron a esta porque viven en el extranjero. De esta forma, cada uno de los hermanos restantes recibió S/ 20 000 más. ¿Cuál de las siguientes expresiones permite calcular lo que recibió cada uno de los hermanos?", opts = listOf("§6*x=4*(x-20000)", "§6*x=4*(x+20000)", "§6*(x-20000)=4*x", "§6*x-20000=4*x"), vals = listOf("solve(6*x=4*(x-20000),x)[0]", "solve(6*x=4*(x+20000),x)[0]", "solve(6*(x-20000)=4*x,x)[0]", "solve(6*x-20000=4*x,x)[0]"), correct = 1, check = "solve(h/4-h/6=20000,h)[0]/6", steps = listOf("Sea x lo que recibiría cada uno si fueran 6. La herencia es 6x.", "Al final son 4 y cada uno recibe x + 20 000. La herencia también es 4(x + 20 000).", "Igualamos: 6x = 4(x + 20 000). Esa es la expresión pedida.", "Resolviendo: 6x = 4x + 80 000, x = 40 000. Cada uno de los cuatro recibió 40 000 + 20 000 = S/ 60 000 y la herencia es S/ 240 000."), note = "Si x se toma como lo que recibió cada uno de los cuatro, la ecuación sería 6(x − 20 000) = 4x, que es la alternativa C. La clave oficial es B, donde x es la parte que habría correspondido entre seis.", theory = "Si una herencia H se reparte entre n personas, cada una recibe H/n. Al cambiar el número de personas cambia la parte de cada uno, pero H es la misma.", idea = "La herencia no cambia: 6 partes de x valen lo mismo que 4 partes de x + 20 000.", mistake = "Restar los 20 000 en lugar de sumarlos: 6x = 4(x − 20 000), alternativa A, da una parte negativa.", verify = "240 000 ÷ 6 = 40 000 y 240 000 ÷ 4 = 60 000. La diferencia es 20 000.", src = "oficial", year = 2024, num = 23, official = 1, review = true))
        l.add(BProb(id = "e24_24", topic = "alg", level = 2, text = "Julio está en una losa deportiva y con su mano lanza hacia arriba una piedra. La altura \"f(t)\" que alcanza esta piedra (en metros), respecto a la losa, en un determinado tiempo \"t\" (en segundos) luego de ser lanzada, se representa por la siguiente función:\n§f(t)=1+10*t-5*t^2\nPara esta situación, ¿cuál de las siguientes gráficas representa adecuadamente la función f(t)?", opts = listOf("Gráfica A", "Gráfica B", "Gráfica C", "Gráfica D"), vals = emptyList(), correct = 0, check = "", steps = listOf("Al inicio, t = 0: f(0) = 1. La piedra sale a 1 m de la losa, desde la mano. Eso descarta B y C, que empiezan en 0.", "Vértice: t = −10/(2·(−5)) = 1 s y f(1) = 1 + 10 − 5 = 6 m. A y D tienen el máximo en (1; 6).", "La piedra cae a la losa cuando f(t) = 0, cerca de t = 2,1 s. Después ya no sigue bajando, porque la losa la detiene.", "La gráfica A termina en la losa. La D sigue por debajo de 0, a alturas negativas que no tienen sentido aquí. La correcta es A."), fig = "x24_24", theory = "Una función cuadrática con coeficiente de t² negativo es una parábola que abre hacia abajo. Su vértice está en t = −b/(2a). En un problema real, el dominio solo incluye los tiempos que tienen sentido.", idea = "Hay tres datos que distinguen las gráficas: dónde empieza, dónde está el punto más alto y dónde termina.", mistake = "Elegir la D porque la parábola coincide con la fórmula, sin fijarse en que la altura no puede ser negativa respecto a la losa.", verify = "5t² − 10t − 1 = 0 da t = 1 + √1,2 ≈ 2,095 s, justo donde termina la curva de la gráfica A.", src = "oficial", year = 2024, num = 24, official = 0, review = true))
        l.add(BProb(id = "e24_25", topic = "geo", level = 2, text = "Se quiere diseñar un tanque formado por un cilindro que está unido en su base a un cono, tal como se muestra en la siguiente figura:\nRecuerda que:\nVolumen del cilindro: V = πr²h. Donde: \"h\" es la altura del cilindro y \"r\" es el radio de la base del cilindro.\nVolumen del cono: V = πr²h/3. Donde: \"h\" es la altura del cono y \"r\" es el radio de la base del cono.\nSi la altura del cilindro es 2 metros y su diámetro 1 metro, ¿cuál será la altura del cono que conforma este tanque, si se requiere que tenga la mitad de capacidad (volumen) del cilindro?", opts = listOf("1 metro", "2 metros", "3 metros", "6 metros"), vals = listOf("1", "2", "3", "6"), correct = 2, check = "solve(pi*(1/2)^2*h/3=pi*(1/2)^2*2/2,h)[0]", steps = listOf("El radio es la mitad del diámetro: r = 0,5 m. Volumen del cilindro: π·0,5²·2 = 0,5π m³.", "El cono debe tener la mitad: 0,25π m³.", "Volumen del cono: π·0,5²·h/3 = 0,25π·h/3.", "Igualamos: 0,25π·h/3 = 0,25π, así que h/3 = 1 y h = 3 m."), fig = "x24_25", theory = "El volumen de un cono es la tercera parte del de un cilindro con la misma base y la misma altura.", idea = "Cono y cilindro tienen la misma base, así que πr² se cancela.", mistake = "Olvidar dividir entre 3 en la fórmula del cono y obtener 1 m, alternativa A.", verify = "Cono de 3 m: π·0,25·3/3 = 0,25π, que es la mitad de 0,5π.", trap = "solve(pi*(1/2)^2*h=pi*(1/2)^2*2/2,h)[0]", src = "oficial", year = 2024, num = 25, trapOpt = 0, official = 2))
        l.add(BProb(id = "e24_26", topic = "est", level = 2, text = "La tabla de frecuencias muestra la distribución de ingresos mensuales de un grupo de recién egresados de un instituto superior tecnológico.\nIngreso mensual de recién egresados\n[tabla]\nLa cantidad de recién egresados que tienen un ingreso mensual entre [S/ 2 000 - S/ 3 500[ es:", opts = listOf("18", "20", "28", "30"), vals = listOf("18", "20", "28", "30"), correct = 2, check = "80-(12+40)", steps = listOf("F de las dos primeras clases: 12 + 40 = 52.", "Tercera clase: f = 60 − 52 = 8. Cuarta: f = 10, así que F = 70. Quinta: f = 80 − 70 = 10.", "Entre S/ 2 000 y S/ 3 500 están las clases 3, 4 y 5: 8 + 10 + 10 = 28."), theory = "La frecuencia absoluta acumulada F de una clase es la suma de las frecuencias f hasta esa clase. Por eso f = F de la clase − F de la clase anterior.", idea = "Lo que está entre 2 000 y 3 500 es todo menos las dos primeras clases.", mistake = "Restar 80 − 60 = 20, alternativa B, y dejar fuera la clase de S/ 2 000 a S/ 2 500.", verify = "Directo: el total es 80 y antes de S/ 2 000 hay 52. Quedan 80 − 52 = 28.", trap = "80-60", src = "oficial", table = listOf(listOf("Ingreso mensual", "Frecuencia absoluta (f)", "Frecuencia absoluta acumulada (F)"), listOf("[S/ 1 000 - S/ 1 500[", "12", ""), listOf("[S/ 1 500 - S/ 2 000[", "40", ""), listOf("[S/ 2 000 - S/ 2 500[", "", "60"), listOf("[S/ 2 500 - S/ 3 000[", "10", ""), listOf("[S/ 3 000 - S/ 3 500[", "", "80")), year = 2024, num = 26, trapOpt = 1, official = 2))
    }
    private fun p7(l: MutableList<BProb>) {
        l.add(BProb(id = "e24_27", topic = "geo", level = 2, text = "En un centro recreativo se tienen dos piscinas en forma de circunferencias tangentes exteriores entre sí. El radio de la circunferencia más grande es igual al diámetro de la otra circunferencia, tal como se muestra en la figura.\nSe desea instalar un puente recto a través de estas piscinas para que los visitantes puedan observar a los peces. El puente se construirá tomando como referencia la longitud del segmento que contiene una cuerda de la circunferencia más grande que pasa por el centro de esta y se prolonga hasta el centro de la circunferencia pequeña.\nPara esta situación, ¿cuál es la longitud del puente expresada en función de R?", opts = listOf("3R", "5R", "6R", "9R"), vals = listOf("3*R", "5*R", "6*R", "9*R"), correct = 1, check = "2*(2*R)+R", steps = listOf("En la figura, R es el radio de la piscina pequeña. Su diámetro es 2R, que es el radio de la grande.", "La cuerda de la grande que pasa por su centro es su diámetro: 2·2R = 4R.", "Esa cuerda termina en el punto de tangencia y se prolonga hasta el centro de la pequeña, una distancia R más.", "Longitud del puente: 4R + R = 5R."), fig = "x24_27", theory = "En dos circunferencias tangentes exteriores, el punto de tangencia está en la recta que une los centros. La cuerda que pasa por el centro es un diámetro.", idea = "El puente es el diámetro de la piscina grande más el radio de la pequeña.", mistake = "Tomar solo la distancia entre los centros, 3R, alternativa A.", verify = "Distancia entre centros: 2R + R = 3R. Desde el extremo lejano de la grande hasta su centro hay 2R. Total 2R + 3R = 5R.", trap = "2*R+R", src = "oficial", year = 2024, num = 27, trapOpt = 0, official = 1))
        l.add(BProb(id = "e24_28", topic = "est", level = 1, text = "En un salón de clase, hay 40 estudiantes cuyas edades van desde 16 hasta 19 años, como se muestra en la siguiente tabla:\nEdades de estudiantes del salón de clase\n[tabla]\nSegún la tabla, ¿cuál es el promedio de las edades de los estudiantes?", opts = listOf("9,89", "17,30", "17,50", "18"), vals = listOf("989/100", "1730/100", "1750/100", "18"), correct = 1, check = "(16*10+17*12+18*14+19*4)/40", steps = listOf("Productos: 16·10 = 160, 17·12 = 204, 18·14 = 252 y 19·4 = 76.", "Suma: 160 + 204 + 252 + 76 = 692.", "Promedio: 692 ÷ 40 = 17,3 años."), theory = "Media de datos con frecuencias: se multiplica cada valor por su frecuencia, se suma y se divide entre el total de datos.", idea = "Cada edad pesa según cuántos estudiantes la tienen.", mistake = "Promediar las cuatro edades sin las frecuencias: 17,5, alternativa C. Dividir 692 entre 70 en lugar de 40 lleva a la A.", verify = "17,3 está entre 16 y 19 y más cerca de 17 y 18, donde hay más estudiantes.", trap = "(16+17+18+19)/4", src = "oficial", table = listOf(listOf("Edad", "Cantidad de estudiantes"), listOf("16", "10"), listOf("17", "12"), listOf("18", "14"), listOf("19", "4")), year = 2024, num = 28, trapOpt = 2, official = 1))
        l.add(BProb(id = "e24_29", topic = "alg", level = 2, text = "Un material biodegradable se descompone con una tasa del 50 % por año. Sabiendo que \"y\" es la fracción del material inicial que queda al transcurrir \"x\" años y está representada por la función: y = 2⁻ˣ.\nPara esta situación, ¿cuál de las siguientes afirmaciones es correcta?", opts = listOf("A los 2 años, el material que queda será 3/4 de su masa original.", "A los 3 años, el material que queda será 1/8 de su masa original.", "A los 4 años, la fracción de material descompuesto será 1/16 de su masa original.", "A los 5 años, la fracción del material descompuesto será 1/32 de su masa original."), vals = listOf("2^(-2)==3/4", "2^(-3)==1/8", "1-2^(-4)==1/16", "1-2^(-5)==1/32"), correct = 1, check = "true", steps = listOf("A: a los 2 años queda 2⁻² = 1/4, no 3/4.", "B: a los 3 años queda 2⁻³ = 1/8. Es correcta.", "C: a los 4 años queda 1/16, así que lo descompuesto es 15/16, no 1/16.", "D: a los 5 años lo descompuesto es 1 − 1/32 = 31/32, no 1/32."), theory = "y = 2⁻ˣ = 1/2ˣ es lo que queda. Lo descompuesto es el resto: 1 − 2⁻ˣ.", idea = "Hay que distinguir lo que queda de lo que ya se descompuso.", mistake = "Confundir lo que queda con lo descompuesto. Por eso C y D parecen correctas.", verify = "Cada año queda la mitad: 1, 1/2, 1/4, 1/8. A los 3 años, 1/8.", src = "oficial", year = 2024, num = 29, official = 1))
        l.add(BProb(id = "e24_30", topic = "ineq", level = 1, text = "Halle el conjunto solución de los valores que puede tomar \"x\" en la siguiente inecuación:\n0 < 3 − x ≤ 4", opts = listOf("]−3; 1]", "]−1; 3]", "[−1; 3[", "[1; 3["), vals = listOf("[-3,1,0,1]", "[-1,3,0,1]", "[-1,3,1,0]", "[1,3,1,0]"), correct = 2, check = "[3-4,3-0,1,0]", steps = listOf("Restamos 3: −3 < −x ≤ 1.", "Multiplicamos por −1 e invertimos: 3 > x ≥ −1.", "Ordenado: −1 ≤ x < 3. El −1 se incluye y el 3 no: [−1; 3[."), theory = "Al multiplicar una desigualdad por un número negativo, el sentido de la desigualdad se invierte.", idea = "Se resta 3 a las tres partes y luego se multiplica por −1, invirtiendo los signos.", mistake = "Invertir los extremos sin cambiar cuál se incluye: ]−1; 3], alternativa B.", verify = "x = −1 da 3 − (−1) = 4, que cumple 0 < 4 ≤ 4. x = 3 da 0, que no cumple 0 < 0.", trap = "[3-4,3-0,0,1]", src = "oficial", year = 2024, num = 30, trapOpt = 1, official = 2))
        l.add(BProb(id = "e25_01", topic = "alg", level = 2, text = "En una empresa se fabrican pernos, los cuales se colocan en bolsas. En cada bolsa se coloca 2⁵ x 3³ pernos. Además, estas bolsas se colocan en paquetes de 2⁴ x 3 bolsas. Para realizar un envío a Arequipa se preparan 2 cajas que contienen 2² x 3² paquetes. ¿Cuántos pernos se enviarán a Arequipa?", opts = listOf("2¹¹ x 3⁶ pernos.", "2¹¹ x 3⁵ pernos.", "2¹² x 3⁶ pernos.", "2² x 3¹⁸ pernos."), vals = listOf("2^11*3^6", "2^11*3^5", "2^12*3^6", "2^2*3^18"), correct = 2, check = "2*(2^2*3^2)*(2^4*3)*(2^5*3^3)", steps = listOf("Pernos = 2 cajas · (2²·3²) paquetes · (2⁴·3) bolsas · (2⁵·3³) pernos.", "Potencias de 2: el 2 de las cajas es 2¹. Exponentes: 1 + 2 + 4 + 5 = 12.", "Potencias de 3: 2 + 1 + 3 = 6.", "Total: 2¹²·3⁶ pernos."), theory = "Producto de potencias de igual base: aᵐ·aⁿ = aᵐ⁺ⁿ. Un número sin exponente escrito tiene exponente 1.", idea = "Se multiplican todos los niveles: cajas, paquetes por caja, bolsas por paquete y pernos por bolsa.", mistake = "Olvidar que son 2 cajas y obtener 2¹¹·3⁶, alternativa a.", verify = "2¹²·3⁶ = 4096·729 = 2 985 984 pernos, y 2·36·48·864 da el mismo número.", trap = "(2^2*3^2)*(2^4*3)*(2^5*3^3)", letters = "abcd", src = "oficial", year = 2025, num = 1, trapOpt = 0, official = 2))
        l.add(BProb(id = "e25_02", topic = "porc", level = 1, text = "María prestó S/ 500 a su amigo Juan para invertir en un negocio con una tasa de interés simple del 40% anual y un plazo de 6 meses. ¿Cuál es el monto que devolverá Juan a María al término del plazo establecido para su préstamo?", opts = listOf("S/ 600.00", "S/ 620.00", "S/ 740.00", "S/ 524.00"), vals = listOf("600", "620", "740", "524"), correct = 0, check = "500+500*40/100*6/12", steps = listOf("Capital 500, tasa 40 % anual = 0,40 y tiempo 6 meses = 0,5 años.", "Interés: 500·0,40·0,5 = 100.", "Monto: 500 + 100 = S/ 600."), theory = "Interés simple: I = C·r·t con la tasa y el tiempo en la misma unidad. Monto = capital + interés.", idea = "La tasa es anual y el plazo está en meses: 6 meses son medio año.", mistake = "Usar los 6 meses como si fueran años o no convertir la tasa. Ninguna alternativa recoge un error típico claro.", verify = "En un año el interés sería 200; en medio año, la mitad: 100.", letters = "abcd", src = "oficial", year = 2025, num = 2, official = 0))
        l.add(BProb(id = "e25_03", topic = "arit", level = 1, text = "Sandra es bióloga y se dedica a estudiar el crecimiento de los árboles. Según su investigación si un árbol crece menos de 15 cm en un año requiere fertilización. Hace un año, uno de los árboles medía 6 metros, desde entonces, el árbol ha crecido 12 cm respecto al año anterior. ¿Qué es lo que reportará Sandra sobre este árbol?", opts = listOf("El árbol no requiere fertilización porque ahora mide 6,12 m.", "El árbol requiere fertilización porque mide menos de 6,15 m.", "El árbol no requiere fertilización porque ha crecido 12 cm.", "El árbol requiere fertilización porque ahora mide más de 6,15 m."), vals = listOf("not(12<15)", "12<15 and 6+12/100<6+15/100", "not(12<15)", "12<15 and 6+12/100>6+15/100"), correct = 1, check = "true", steps = listOf("El árbol creció 12 cm, que es menos de 15 cm. Entonces requiere fertilización. Eso descarta a y c.", "Ahora mide 6 m + 12 cm = 6,12 m.", "Si hubiera crecido 15 cm mediría 6,15 m. Como mide 6,12 m, mide menos de 6,15 m: la razón de b es correcta.", "La d dice que mide más de 6,15 m, lo cual es falso."), theory = "Para comparar medidas se usan las mismas unidades: 1 m = 100 cm.", idea = "Lo que decide es el crecimiento del año: 12 cm es menos que 15 cm.", mistake = "Pensar que como el árbol creció, ya no necesita fertilización. La regla depende de cuánto creció, no de si creció.", verify = "6,12 < 6,15 equivale a 12 cm < 15 cm de crecimiento.", letters = "abcd", src = "oficial", year = 2025, num = 3, official = 1))
        l.add(BProb(id = "e25_04", topic = "frac", level = 1, text = "Se sabe que algunas raíces cuadradas tienen infinitas cifras decimales, por ejemplo:\n√5 = 2,2360679774 ...\n¿Cuál es el valor aproximado a las centésimas de √5 ?", opts = listOf("2,2", "2,24", "2,23", "2,236"), vals = listOf("22/10", "224/100", "223/100", "2236/1000"), correct = 1, check = "round(evalf(sqrt(5),20)*100)/100", steps = listOf("√5 = 2,2360679…", "Dos decimales: 2,23. El tercer decimal es 6, que es mayor o igual que 5.", "Se sube la cifra de las centésimas: 2,24."), theory = "Para aproximar a las centésimas se conservan dos decimales y se mira el tercero: si es 5 o más, se sube la segunda cifra.", idea = "El tercer decimal de 2,236… es 6, así que se redondea hacia arriba.", mistake = "Cortar sin redondear y escribir 2,23, alternativa c.", verify = "2,24 − 2,236… = 0,0039…, menos de media centésima. Es la centésima más cercana.", trap = "floor(evalf(sqrt(5),20)*100)/100", letters = "abcd", src = "oficial", year = 2025, num = 4, trapOpt = 2, official = 1))
    }
    private fun p8(l: MutableList<BProb>) {
        l.add(BProb(id = "e25_05", topic = "arit", level = 1, text = "La masa del átomo de Hierro es 166 x 10⁻²⁹ Kg. ¿Cuál es la masa de este átomo expresada en notación científica?", opts = listOf("1,66 x 10⁻²⁷ kg", "0,166 x 10⁻²⁸ kg", "1,66 x 10⁻²⁹ kg", "16,6 x 10⁻²⁶ kg"), vals = listOf("166/100*10^(-27)==166*10^(-29) and 166/100>=1 and 166/100<10", "166/1000*10^(-28)==166*10^(-29) and 166/1000>=1", "166/100*10^(-29)==166*10^(-29)", "166/10*10^(-26)==166*10^(-29) and 166/10<10"), correct = 0, check = "true", steps = listOf("Escribimos 166 en notación científica: 166 = 1,66 × 10².", "Entonces 166 × 10⁻²⁹ = 1,66 × 10² × 10⁻²⁹.", "Sumamos exponentes: 2 + (−29) = −27. Resultado: 1,66 × 10⁻²⁷ kg."), theory = "Notación científica: a × 10ⁿ con 1 ≤ a < 10. Si la coma se mueve a la izquierda, el exponente sube; si se mueve a la derecha, baja.", idea = "166 = 1,66 × 10², así que se suman 2 al exponente.", mistake = "Mover la coma sin cambiar el exponente: 1,66 × 10⁻²⁹, alternativa c, que es cien veces menor.", verify = "1,66 × 10⁻²⁷ = 166 × 10⁻²⁹ porque 1,66 = 166 × 10⁻².", letters = "abcd", src = "oficial", year = 2025, num = 5, official = 0))
        l.add(BProb(id = "e25_06", topic = "frac", level = 1, text = "Para los invitados de una fiesta, se sirvieron agua y limonada en vasos.\nSegún esta situación, ¿cuál de las siguientes afirmaciones es correcta?", opts = listOf("La cantidad de vasos de agua es 3/8 de la cantidad de vasos de limonada", "La cantidad de vasos de agua es 5/3 de la cantidad de vasos de limonada", "La cantidad de vasos de agua es 8/3 de la cantidad de vasos de limonada", "La cantidad de vasos de agua es 3/5 de la cantidad de vasos de limonada"), vals = listOf("3/5==3/8", "3/5==5/3", "3/5==8/3", "3/5==3/5"), correct = 3, check = "true", steps = listOf("En la figura hay 3 vasos de agua y 5 de limonada.", "Agua entre limonada: 3/5.", "La cantidad de vasos de agua es 3/5 de la de limonada."), fig = "x25_06", theory = "Decir que A es la fracción p/q de B significa A = (p/q)·B, es decir A/B = p/q.", idea = "Se cuentan los vasos y se divide agua entre limonada, en ese orden.", mistake = "Dividir entre el total de vasos, 3/8, alternativa a. Ese número compara el agua con todos los vasos, no con la limonada.", verify = "3/5 de 5 vasos son 3 vasos.", letters = "abcd", src = "oficial", year = 2025, num = 6, official = 3))
        l.add(BProb(id = "e25_07", topic = "ineq", level = 2, text = "Sean los intervalos A= [-2; 2[  y  B= ]-1;+∞ [.\n¿Cuál es la representación del conjunto (A – B) U (B – A)?", opts = listOf("[ −2: −1] U [2; + ∞[", "] − 2: −1[ U ]2; + ∞[", "] − 2: −1[ U [−1; + ∞[", "[−2: −1] U [ 1; + ∞["), vals = listOf("[[-2,-1,1,1],[2,inf,1,0]]", "[[-2,-1,0,0],[2,inf,0,0]]", "[[-2,-1,0,0],[-1,inf,1,0]]", "[[-2,-1,1,1],[1,inf,1,0]]"), correct = 0, check = "[[-2,-1,1,1],[2,inf,1,0]]", steps = listOf("A va de −2 a 2, con −2 incluido y 2 excluido. B va de −1 al infinito, con −1 excluido.", "A − B: los números de A que no están en B son los de −2 a −1. El −1 no está en B, así que sí se incluye: [−2; −1].", "B − A: los números de B que no están en A empiezan en 2. El 2 no está en A pero sí en B, así que se incluye: [2; +∞[.", "Unión: [−2; −1] ∪ [2; +∞[."), note = "En el original los extremos −2 y −1 aparecen separados con dos puntos y la unión con la letra U. Se respeta tal como está escrito.", theory = "A − B son los elementos de A que no están en B. La unión (A − B) ∪ (B − A) es la diferencia simétrica: lo que está en uno solo de los dos conjuntos.", idea = "Se dibujan los dos intervalos en la recta y se ve qué parte está en uno solo.", mistake = "Olvidar que −1 y 2 sí pertenecen porque cada uno está en un solo conjunto, y escribir los extremos abiertos como en b.", verify = "−1 está en A y no en B: pertenece. 0 está en ambos: no pertenece. 2 está solo en B: pertenece.", letters = "abcd", src = "oficial", year = 2025, num = 7, official = 0))
        l.add(BProb(id = "e25_08", topic = "porc", level = 2, text = "Sebastián decide comprar un televisor cuyo precio original es S/ 2 500. Él visita dos tiendas de artefactos y observa las ofertas.\nTIENDA A: 20% de descuento + 12% de descuento adicional por aniversario.\nTIENDA B: 26 % de descuento + 5% de descuento adicional pagando con tarjeta.\n¿En qué tienda le resulta más conveniente comprar su televisor? ¿Por qué?", opts = listOf("En la tienda A, porque presenta descuentos sucesivos de 20% y 12%.", "En la tienda B, porque el descuento total es de 31%.", "En la tienda A, porque el precio es menor que en la tienda B.", "En la tienda B, porque el precio es menor que en la tienda A."), vals = listOf("2500*80/100*88/100<2500*74/100*95/100", "2500*74/100*95/100<2500*80/100*88/100 and 1-74/100*95/100==31/100", "2500*80/100*88/100<2500*74/100*95/100", "2500*74/100*95/100<2500*80/100*88/100"), correct = 3, check = "true", steps = listOf("Tienda A: 2500·0,80 = 2000 y luego 2000·0,88 = S/ 1760.", "Tienda B: 2500·0,74 = 1850 y luego 1850·0,95 = S/ 1757,50.", "En la tienda B paga menos, S/ 1757,50 contra S/ 1760. Conviene la B porque su precio es menor.", "El descuento total en B no es 31 %: se paga 0,74·0,95 = 70,3 %, así que el descuento es 29,7 %."), theory = "Descuentos sucesivos: se multiplican los porcentajes que se pagan. Por eso no se suman.", idea = "Se calcula el precio final en cada tienda y se comparan.", mistake = "Sumar los descuentos: 20 + 12 = 32 % en A y 26 + 5 = 31 % en B, y concluir que conviene A. Los descuentos sucesivos no se suman.", verify = "Diferencia: 1760 − 1757,50 = S/ 2,50 a favor de la tienda B.", letters = "abcd", src = "oficial", year = 2025, num = 8, official = 3))
        l.add(BProb(id = "e25_09", topic = "prop", level = 1, text = "Percy atiende en el cafetín de un colegio, para hoy él ha preparado platos de arroz con pollo. En la siguiente tabla se muestra la cantidad de platos y precio que se paga por ellos.\n[tabla]\n¿Cuál de las siguientes expresiones representa la relación entre la cantidad de platos y los precios en soles?", opts = listOf("y = 6 / x", "y = 6 x", "y = 6 + x", "x = 6 y"), vals = listOf("6/x", "6*x", "6+x", "x/6"), correct = 1, check = "54/9*x", steps = listOf("18/3 = 6, 54/9 = 6, 72/12 = 6 y 90/15 = 6.", "El cociente y/x siempre es 6: el precio es 6 veces la cantidad de platos.", "La relación es y = 6x."), theory = "Dos magnitudes son directamente proporcionales si su cociente es constante. Entonces y = k·x, donde k es esa constante.", idea = "Se divide cada precio entre su cantidad de platos.", mistake = "Invertir las variables y escribir x = 6y, alternativa d.", verify = "Con x = 15: 6·15 = 90, como en la tabla.", trap = "x/6", letters = "abcd", src = "oficial", table = listOf(listOf("Cantidad de platos de arroz con pollo (x)", "3", "9", "12", "15"), listOf("Precio en soles (y)", "18", "54", "72", "90")), year = 2025, num = 9, trapOpt = 3, official = 1))
        l.add(BProb(id = "e25_10", topic = "ecu", level = 1, text = "Los hermanos Joaquín y Pedro venden chocolates de diferentes tamaños en la feria del pueblo. Joaquín vende sus chocolates a S/ 2 y Pedro los vende a S/3. Cierto día, ellos obtuvieron S/ 55 por la venta de todos los chocolates.\nSi ese día, Joaquín vendió 10 chocolates más de los que vendió Pedro, ¿cuánto obtuvo Pedro por la venta de todos sus chocolates?", opts = listOf("S/ 11", "S/ 21", "S/ 33", "S/ 34"), vals = listOf("11", "21", "33", "34"), correct = 1, check = "3*solve(2*(p+10)+3*p=55,p)[0]", steps = listOf("Sea p el número de chocolates de Pedro. Joaquín vendió p + 10.", "Dinero total: 2(p + 10) + 3p = 55.", "2p + 20 + 3p = 55, así que 5p = 35 y p = 7 chocolates.", "Pedro obtuvo 3·7 = S/ 21."), theory = "Planteo con una incógnita: se nombra lo desconocido y se escribe la condición del total.", idea = "Lo que se pide es el dinero de Pedro, no la cantidad de chocolates.", mistake = "Responder lo que obtuvo Joaquín, S/ 34, alternativa d.", verify = "Joaquín vendió 17 y obtuvo 34. Pedro obtuvo 21. Total 34 + 21 = 55.", trap = "2*(solve(2*(p+10)+3*p=55,p)[0]+10)", letters = "abcd", src = "oficial", year = 2025, num = 10, trapOpt = 3, official = 1))
        l.add(BProb(id = "e25_11", topic = "ecu", level = 1, text = "Carlos vende casacas en una tienda de ropa en Lima. Él compra las casacas a un mayorista de Puno al precio de S/ 45 cada una. Este mayorista le envía las casacas por encomienda hacia Lima por un precio de 35 soles.\nSabiendo que \"x\" representa el número de casacas e \"y\" el monto total a pagar por la compra, ¿cuál de las siguientes expresiones representa la relación correcta entre \"x\" en \"y\"?", opts = listOf("y = 35 x", "y = 45 x", "y = 35 x + 45", "y = 45 x + 35"), vals = listOf("35*x", "45*x", "35*x+45", "45*x+35"), correct = 3, check = "45*x+35", steps = listOf("x casacas a S/ 45 cuestan 45x.", "La encomienda cuesta S/ 35 en total, sin importar la cantidad.", "Monto total: y = 45x + 35."), note = "En el original dice entre \"x\" en \"y\"; se respeta tal como está escrito.", theory = "Costo total = precio por unidad × cantidad + costo fijo. El envío es un solo pago, no depende de cuántas casacas sean.", idea = "El envío de 35 soles se paga una vez; cada casaca cuesta 45.", mistake = "Intercambiar los números y escribir y = 35x + 45, alternativa c.", verify = "Con 2 casacas: 45·2 + 35 = 125 soles.", trap = "35*x+45", letters = "abcd", src = "oficial", year = 2025, num = 11, trapOpt = 2, official = 3))
        l.add(BProb(id = "e25_12", topic = "alg", level = 2, text = "Matías es un futbolista, en un partido patea la pelota desde el suelo y hacia arriba. La pelota describe una trayectoria parabólica y se toma en cuenta hasta que cae la pelota al campo de juego. La siguiente gráfica representa la relación entre el tiempo en segundos y la altura en metros.\nSegún la gráfica ¿Cuál de las siguientes afirmaciones es correcta?", opts = listOf("La altura máxima que alcanza la pelota por el lanzamiento de Matías es 6 m.", "La pelota alcanza dos veces la altura de 8 m.", "El tiempo que demora la pelota en llegar al suelo es 7 s.", "La pelota alcanza una vez la altura de 5 m."), vals = listOf("6*3-3^2==6", "size(solve(6*t-t^2=8,t))==2", "max(solve(6*t-t^2=0,t))==7", "size(solve(6*t-t^2=5,t))==1"), correct = 1, check = "true", steps = listOf("De la gráfica: la pelota sale en t = 0, llega a 9 m en t = 3 y cae al suelo en t = 6. Sus puntos cumplen f(t) = 6t − t².", "a: la altura máxima es 9 m, no 6 m.", "b: la altura 8 m se alcanza en t = 2 al subir y en t = 4 al bajar: dos veces. Es correcta.", "c: llega al suelo en 6 s, no en 7 s.", "d: 5 m se alcanza en t = 1 y en t = 5: dos veces, no una."), fig = "x25_12", theory = "En una parábola que abre hacia abajo, cada altura menor que la máxima se alcanza dos veces: una al subir y otra al bajar. La máxima se alcanza una sola vez, en el vértice.", idea = "Una recta horizontal a la altura pedida corta la curva en dos puntos si está por debajo del vértice.", mistake = "Confundir el tiempo en que llega al suelo con el último número del eje, 7 s, como en la alternativa c.", verify = "f(2) = 12 − 4 = 8 y f(4) = 24 − 16 = 8.", letters = "abcd", src = "oficial", year = 2025, num = 12, official = 1))
    }
    private fun p9(l: MutableList<BProb>) {
        l.add(BProb(id = "e25_13", topic = "alg", level = 1, text = "En la siguiente ecuación: (x + 2)(x + 3) = 12.\n¿Cuál de los siguientes conjuntos incluye a las soluciones de la ecuación?", opts = listOf("{10, 9}", "{-6, -4}", "{-6, 1, 3}", "{-6, -1, 2}"), vals = listOf("size(select(r->contains([10,9],r)>0,solve((x+2)*(x+3)=12,x)))==2", "size(select(r->contains([-6,-4],r)>0,solve((x+2)*(x+3)=12,x)))==2", "size(select(r->contains([-6,1,3],r)>0,solve((x+2)*(x+3)=12,x)))==2", "size(select(r->contains([-6,-1,2],r)>0,solve((x+2)*(x+3)=12,x)))==2"), correct = 2, check = "true", steps = listOf("Desarrollamos: x² + 5x + 6 = 12.", "Igualamos a cero: x² + 5x − 6 = 0.", "Factorizamos: (x + 6)(x − 1) = 0. Soluciones: x = −6 y x = 1.", "El conjunto que incluye a −6 y a 1 es {−6, 1, 3}."), theory = "Si un producto es igual a un número distinto de cero, no se puede igualar cada factor a ese número. Hay que desarrollar, igualar a cero y factorizar.", idea = "Primero se iguala a cero: no sirve decir que x + 2 = 12 o x + 3 = 12.", mistake = "Igualar cada factor a 12: x = 10 y x = 9, alternativa a.", verify = "(−6 + 2)(−6 + 3) = (−4)(−3) = 12 y (1 + 2)(1 + 3) = 3·4 = 12.", letters = "abcd", src = "oficial", year = 2025, num = 13, official = 2))
        l.add(BProb(id = "e25_14", topic = "suc", level = 1, text = "En la siguiente sucesión:   5; 8; 11; 14; …\n¿Cuál es la suma de los 9 primeros términos de la sucesión?", opts = listOf("17", "29", "136", "153"), vals = listOf("17", "29", "136", "153"), correct = 3, check = "sum(5+3*(k-1),k,1,9)", steps = listOf("Primer término 5 y razón 3.", "Noveno término: 5 + 8·3 = 29.", "Suma: 9·(5 + 29)/2 = 9·17 = 153."), theory = "Progresión aritmética: aₙ = a₁ + (n − 1)·r. Suma de n términos: Sₙ = n·(a₁ + aₙ)/2.", idea = "Cada término suma 3. Se halla el noveno término y se usa la fórmula de la suma.", mistake = "Responder el noveno término, 29, alternativa b, en lugar de la suma.", verify = "Sumando uno por uno: 5 + 8 + 11 + 14 + 17 + 20 + 23 + 26 + 29 = 153.", trap = "5+8*3", letters = "abcd", src = "oficial", year = 2025, num = 14, trapOpt = 1, official = 3))
        l.add(BProb(id = "e25_15", topic = "ecu", level = 1, text = "Margarita es comerciante y recibe un pago de S/ 990, al contar el dinero observa que le han pagado solo con billetes de S/ 10 y de S/ 20. Además, la cantidad de billetes de S/ 20 excede en 15 a la cantidad de billetes de S/ 10.\nSi \"x\" representa la cantidad de billetes de S/10 e \"y\" representa la cantidad de billetes de S/ 20, la situación anterior se representa mediante el siguiente sistema de ecuaciones:\n10 x + 20 y = 990\ny − x = 15\n¿Cuántos billetes en total tiene Margarita?", opts = listOf("38", "59", "61", "71"), vals = listOf("38", "59", "61", "71"), correct = 2, check = "sum(linsolve([10*x+20*y=990,y-x=15],[x,y]))", steps = listOf("De y − x = 15: y = x + 15.", "Reemplazamos: 10x + 20(x + 15) = 990, es decir 30x + 300 = 990.", "30x = 690, x = 23 billetes de S/ 10, y y = 38 billetes de S/ 20.", "Total: 23 + 38 = 61 billetes."), theory = "Sistema por sustitución: se despeja una incógnita y se reemplaza en la otra ecuación.", idea = "Se pide el total de billetes: x + y, no solo uno de ellos.", mistake = "Responder solo los billetes de S/ 20, 38, alternativa a.", verify = "23·10 + 38·20 = 230 + 760 = 990 y 38 − 23 = 15.", trap = "linsolve([10*x+20*y=990,y-x=15],[x,y])[1]", letters = "abcd", src = "oficial", year = 2025, num = 15, trapOpt = 0, official = 2))
        l.add(BProb(id = "e25_16", topic = "ineq", level = 1, text = "En la siguiente inecuación: 3(x + 2) - 3 < 9\n¿Cuál es el conjunto solución de esta inecuación?", opts = listOf("x < 2", "x > 2", "x < 4", "x > 3"), vals = listOf("x<2", "x>2", "x<4", "x>3"), correct = 0, check = "solve(3*(x+2)-3<9,x)[0]", steps = listOf("Desarrollamos: 3x + 6 − 3 < 9, es decir 3x + 3 < 9.", "Restamos 3: 3x < 6.", "Dividimos entre 3: x < 2."), theory = "Una inecuación lineal se resuelve como una ecuación. Solo se invierte el signo si se multiplica o divide por un número negativo.", idea = "Se dividen ambos lados entre 3, que es positivo, así que el signo no cambia.", mistake = "Invertir el signo sin motivo y escribir x > 2, alternativa b.", verify = "Con x = 1: 3·3 − 3 = 6 < 9, cumple. Con x = 2: 3·4 − 3 = 9, que no es menor que 9.", trap = "x>2", letters = "abcd", src = "oficial", year = 2025, num = 16, trapOpt = 1, official = 0))
        l.add(BProb(id = "e25_17", topic = "alg", level = 2, text = "Sofia realizó un experimento con bacterias. Ella registró los datos de su experimento y contabilizó 120 bacterias al inicio. Además, durante el experimento observó que las bacterias se reproducían según la función f(x) = 120.2ˣ\n\"x\" representa el tiempo en periodos de tres horas.\nLuego de 15 horas, Sofia afirma que la cantidad de bacterias es 15 x 120.\n¿Es verdadero o falso lo afirmado por Sofía? ¿Por qué?", opts = listOf("Es falso, porque dicha cantidad debe ser 32 veces la cantidad de bacterias que había al inicio.", "Es verdad, porque cada tres horas la cantidad de bacterias se incrementó en 120.", "Es falso, porque la cantidad de bacterias se multiplica 10 veces después de 15 horas.", "Es verdad, porque cada tres horas la cantidad de bacterias se duplica y genera 15 veces la cantidad inicial."), vals = listOf("120*2^(15/3)==32*120 and 120*2^(15/3)!=15*120", "120*2^(15/3)==15*120", "120*2^(15/3)==10*120 and 120*2^(15/3)!=15*120", "120*2^(15/3)==15*120"), correct = 0, check = "true", steps = listOf("15 horas son 15 ÷ 3 = 5 periodos, así que x = 5.", "f(5) = 120·2⁵ = 120·32 = 3840 bacterias.", "Es 32 veces la cantidad inicial, no 15 veces. Sofía se equivoca.", "La alternativa a lo explica correctamente."), note = "En el original la función aparece escrita 120.2ˣ; el punto indica multiplicación: 120·2ˣ.", theory = "Crecimiento exponencial: en f(x) = a·2ˣ la cantidad se duplica en cada periodo. Después de x periodos es 2ˣ veces la inicial.", idea = "Primero se convierten las 15 horas a periodos de 3 horas.", mistake = "Pensar que crece la misma cantidad cada periodo, como en la alternativa b. Eso sería crecimiento lineal.", verify = "Periodo a periodo: 120, 240, 480, 960, 1920, 3840. Son 5 duplicaciones.", letters = "abcd", src = "oficial", year = 2025, num = 17, official = 0))
        l.add(BProb(id = "e25_18", topic = "est", level = 2, text = "Grecia es la dueña de una tienda de productos cosméticos y hace un estudio de mercado sobre la proyección de ventas de una crema. La gráfica muestra la función que relaciona de la cantidad de cremas vendidas al transcurrir las semanas.\n¿Cuál de las siguientes afirmaciones NO es válida según la información presentada?", opts = listOf("La función es creciente porque a mayor cantidad de semanas, mayor es la cantidad de productos vendidos.", "Según el estudio de mercado se alcanza como máximo volumen de ventas 204 cremas en el tiempo considerado.", "En la séptima semana se alcanzó una cantidad de 84 cremas vendidas dado que a partir de esta semana se cumple que f(x) = 12x.", "El número de semanas y la cantidad de cremas son números enteros y expresan cantidades exactas."), vals = listOf("min(6-0,14-6,24-14,36-24,50-36,66-50,84-66,104-84,126-104,150-126,176-150,204-176)>0", "max(0,6,14,24,36,50,66,84,104,126,150,176,204)==204", "84==12*7 and 104==12*8 and 126==12*9 and 150==12*10", "true"), correct = 2, check = "false", steps = listOf("a: los valores 0, 6, 14, 24, … siempre aumentan. Es válida.", "b: el mayor valor en las 12 semanas es 204. Es válida.", "c: en la semana 7, 12·7 = 84, que coincide. Pero en la semana 8, 12·8 = 96 y la gráfica dice 104. La fórmula no se cumple a partir de la semana 7. No es válida.", "d: semanas y cremas son conteos enteros. Es válida."), fig = "x25_18", theory = "Una función es creciente si al aumentar x también aumenta y. Para que una fórmula valga desde un punto en adelante, debe cumplirse en todos los puntos siguientes.", idea = "Se prueba la fórmula f(x) = 12x con los datos de la semana 7 en adelante.", mistake = "Comprobar la fórmula solo en la semana 7 y no en las siguientes.", verify = "Los datos cumplen f(x) = x² + 5x: f(7) = 49 + 35 = 84 y f(8) = 64 + 40 = 104.", letters = "abcd", src = "oficial", year = 2025, num = 18, official = 2, review = true))
        l.add(BProb(id = "e25_19", topic = "geo", level = 2, text = "Mateo vive en una zona donde llega el servicio de agua potable por horas, él cuenta con un tanque cilíndrico en su casa para almacenar agua. Hoy logró llenar el tanque hasta la mitad de su capacidad y luego se cortó el servicio.\nMateo necesita las ¾ partes de la capacidad del tanque de agua para abastecer a su casa hasta que vuelva el servicio de agua.\n¿Qué debe hacer Mateo para saber la cantidad de agua que le falta para abastecer a su casa?", opts = listOf("Calcular el volumen de agua considerando que la altura que alcanza es de 0,6 m.", "Calcular la altura que debió alcanzar el agua que necesita.", "Calcular el volumen de agua considerando una altura de 0,3 m.", "Calcular el volumen del tanque y restar el volumen de agua que logró recolectar."), vals = listOf("6/10", "12/10*3/4", "3/10", "12/10-6/10"), correct = 2, check = "12/10*(3/4-1/2)", steps = listOf("Altura del tanque: 1,2 m. Tiene agua hasta la mitad: 0,6 m.", "Necesita 3/4 de la capacidad: hasta 0,9 m.", "Le falta la diferencia: 0,9 − 0,6 = 0,3 m de altura de agua.", "Para saber cuánta agua le falta, debe calcular el volumen de un cilindro de radio 0,5 m y altura 0,3 m. Es la alternativa c."), fig = "x25_19", theory = "En un cilindro el volumen es proporcional a la altura del agua: V = πr²·h. Una fracción de la capacidad corresponde a la misma fracción de la altura.", idea = "Le falta llegar de 1/2 a 3/4 del tanque: le falta 1/4 de la altura.", mistake = "Calcular lo que falta para llenar todo el tanque, como en la d. Mateo no necesita el tanque lleno, solo 3/4.", verify = "π·0,5²·0,3 = 0,075π m³ ≈ 0,236 m³, que es la cuarta parte del tanque: π·0,25·1,2/4 = 0,075π.", trap = "12/10-6/10", letters = "abcd", src = "oficial", year = 2025, num = 19, trapOpt = 3, official = 2, review = true))
        l.add(BProb(id = "e25_20", topic = "geo", level = 3, text = "Isabella desea construir un vivero. Se trata de una estructura compuesta por un cubo y una pirámide de base cuadrada. Esta estructura está formada por tubos de fierro grueso en cada arista y algunas diagonales de las caras del cubo, para luego ser revestida de malla.\nSi la altura del cubo mide 2 m y las aristas de las caras laterales de la pirámide miden √5 m ¿Cuántos metros de tubo de fierro se necesitan para formar la estructura?", opts = listOf("(24 + 4√2 + 4√5 ) m de tubo de fierro.", "(12 + 8√2 + 4√5 ) m de tubo de fierro.", "(20 + 4√2 + 4√5 ) m de tubo de fierro.", "(24 + 8√2 + 4√5 ) m de tubo de fierro."), vals = listOf("24+4*sqrt(2)+4*sqrt(5)", "12+8*sqrt(2)+4*sqrt(5)", "20+4*sqrt(2)+4*sqrt(5)", "24+8*sqrt(2)+4*sqrt(5)"), correct = 3, check = "12*2+4*sqrt(2^2+2^2)+4*sqrt(5)", steps = listOf("Aristas del cubo: 12 de 2 m cada una: 24 m.", "Pirámide: su base es la cara superior del cubo, ya contada. Solo se suman sus 4 aristas laterales de √5 m: 4√5 m.", "En la figura, la cara izquierda y la cara derecha del cubo tienen cada una sus dos diagonales cruzadas. La cara del frente tiene la puerta y no lleva diagonales. Son 4 diagonales.", "Cada diagonal mide 2√2 m, porque la cara es un cuadrado de lado 2. Las 4 suman 8√2 m.", "Total: 24 + 8√2 + 4√5 metros."), fig = "x25_20", theory = "Un cubo tiene 12 aristas. La diagonal de un cuadrado de lado a mide a√2. La base de la pirámide coincide con la cara de arriba del cubo, así que sus aristas no se cuentan dos veces.", idea = "Hay que contar en la figura cuántas diagonales de caras tienen tubo.", mistake = "Contar las 4 diagonales como si midieran √2 cada una, o contar solo dos diagonales: así sale 4√2, como en la alternativa a.", verify = "Con decimales: 24 + 11,31 + 8,94 ≈ 44,26 m de tubo.", trap = "12*2+2*sqrt(2^2+2^2)+4*sqrt(5)", letters = "abcd", src = "oficial", year = 2025, num = 20, trapOpt = 0, official = 3))
    }
    private fun p10(l: MutableList<BProb>) {
        l.add(BProb(id = "e25_21", topic = "geo", level = 1, text = "En un mapa se encuentran ubicados tres caseríos formando un triángulo. Se desea construir una posta médica a igual distancia de cada caserío.\nConsiderando los puntos notables del triángulo que se forma con estos tres caseríos, ¿en cuál de estos puntos se debe construir la posta médica?", opts = listOf("En el incentro.", "En el circuncentro.", "En el baricentro.", "En el ortocentro."), vals = emptyList(), correct = 1, check = "", steps = listOf("Cada punto de la mediatriz de un lado está a igual distancia de los extremos de ese lado.", "El punto donde se cortan las tres mediatrices está a igual distancia de los tres vértices.", "Ese punto es el circuncentro, centro de la circunferencia que pasa por los tres caseríos."), theory = "Circuncentro: punto donde se cortan las mediatrices; está a igual distancia de los tres vértices. Incentro: a igual distancia de los tres lados. Baricentro: corte de las medianas. Ortocentro: corte de las alturas.", idea = "La posta debe estar a igual distancia de los tres caseríos, que son los vértices.", mistake = "Elegir el incentro, que equidista de los lados del triángulo y no de los vértices.", verify = "Si el triángulo fuera rectángulo, el circuncentro estaría en el punto medio de la hipotenusa, a igual distancia de los tres vértices.", letters = "abcd", src = "oficial", year = 2025, num = 21, official = 1))
        l.add(BProb(id = "e25_22", topic = "geo", level = 1, text = "El jardín de una huerta tiene forma de rombo y se subdivide en regiones más pequeñas mediante la colocación de dos cercas, cada una de ellas uniendo los vértices opuestos del rombo, como se muestra en la siguiente figura.\nSi el área de una de las regiones más pequeñas que resultan es 90 m², ¿cuál es el área total del jardín de esta huerta?", opts = listOf("90 m²", "180 m²", "360 m²", "720 m²"), vals = listOf("90", "180", "360", "720"), correct = 2, check = "4*90", steps = listOf("Las cercas unen vértices opuestos: son las diagonales del rombo.", "Las diagonales se cortan en su punto medio y son perpendiculares, así que forman 4 triángulos rectángulos iguales.", "Área total: 4·90 = 360 m²."), fig = "x25_22", theory = "Las diagonales de un rombo se cortan perpendicularmente en sus puntos medios y lo dividen en cuatro triángulos rectángulos iguales.", idea = "Las dos cercas son las diagonales: forman 4 regiones iguales.", mistake = "Pensar que una sola cerca divide en 2 partes y responder 180 m², alternativa b.", verify = "Con la fórmula del rombo: D·d/2. Cada triángulo tiene catetos D/2 y d/2, con área D·d/8 = 90. Entonces D·d/2 = 4·90 = 360.", trap = "2*90", letters = "abcd", src = "oficial", year = 2025, num = 22, trapOpt = 1, official = 2))
        l.add(BProb(id = "e25_23", topic = "geo", level = 2, text = "Una torta circular tiene distribuidas 8 fresas en todo su perímetro, de manera que la distancia entre dos fresas consecutivas es siempre la misma. La mayor distancia que puede haber entre dos fresas cualesquiera es 24 cm.\nSi se desea colocar la torta en una caja de base cuadrada de manera que la torta entre exactamente, ¿cuál es el perímetro que debe tener la base de esta caja?", opts = listOf("24 cm", "48 cm", "96 cm", "144 cm"), vals = listOf("24", "48", "96", "144"), correct = 2, check = "4*24", steps = listOf("Con 8 fresas igualmente espaciadas, cada fresa tiene otra justo al frente. La mayor distancia, 24 cm, es el diámetro.", "Si la torta entra exactamente, el lado de la base cuadrada es igual al diámetro: 24 cm.", "Perímetro de la base: 4·24 = 96 cm."), theory = "La mayor distancia entre dos puntos de una circunferencia es el diámetro. Un círculo que entra exactamente en un cuadrado tiene diámetro igual al lado del cuadrado.", idea = "Con 8 fresas iguales espaciadas, hay fresas diametralmente opuestas: su distancia es el diámetro.", mistake = "Usar el radio como lado: 4·12 = 48 cm, alternativa b.", verify = "El radio es 12 cm; el círculo toca los cuatro lados de un cuadrado de 24 cm de lado.", trap = "4*12", letters = "abcd", src = "oficial", year = 2025, num = 23, trapOpt = 1, official = 2))
        l.add(BProb(id = "e25_24", topic = "trig", level = 2, text = "Durante los primeros segundos de su lanzamiento, un cohete despega verticalmente desde el suelo. En el instante en que el cohete ha recorrido 2 km, un observador de la base de operaciones, que se encuentra a una distancia d = 2√3 km del punto de lanzamiento lo puede ver con un ángulo de elevación de 30°. Luego de unos segundos vuelve a observar el cohete y esta vez el ángulo de elevación se ha duplicado a 60°. Observa:\n¿Cuál es la distancia \"h\" que recorrió el cohete entre los dos momentos observados?", opts = listOf("2 km", "4 km", "6 km", "8 km"), vals = listOf("2", "4", "6", "8"), correct = 1, check = "2*sqrt(3)*tan(pi/3)-2", steps = listOf("Distancia horizontal: 2√3 km. Con 30°, la altura es 2√3·tan 30° = 2√3·(1/√3) = 2 km, como dice el enunciado.", "Con 60°: altura total = 2√3·tan 60° = 2√3·√3 = 6 km.", "Recorrido entre los dos momentos: h = 6 − 2 = 4 km."), fig = "x25_24", theory = "En un triángulo rectángulo, tan θ = cateto opuesto / cateto adyacente. tan 60° = √3.", idea = "Con el ángulo de 60° se halla la altura total; h es esa altura menos los 2 km iniciales.", mistake = "Responder la altura total, 6 km, alternativa c, sin restar los 2 km iniciales.", verify = "En la figura los dos ángulos de 30° se suman a 60°, y la altura total 2 + 4 = 6 km cumple tan 60° = 6/(2√3) = √3.", trap = "2*sqrt(3)*tan(pi/3)", letters = "abcd", src = "oficial", year = 2025, num = 24, trapOpt = 2, official = 1))
        l.add(BProb(id = "e25_25", topic = "geo", level = 2, text = "El hexágono regular ABCDEF, con centro O, representa la forma de una plaza que es usada para jugar por tres niños: Pedro, Luis y Max. Ellos están jugando a recorrer distancias por diversos caminos y ganará aquel que recorra una mayor distancia.\nObserva:\nPedro recorre el camino ABOD, Luis recorre el camino ABED y Max recorre el camino ABOCD.\n¿Cuál de las siguientes afirmaciones es correcta?", opts = listOf("Max recorre más distancia que Luis.", "Pedro recorre igual distancia que Luis.", "Max recorre menos distancia que Pedro.", "Luis recorre igual distancia que Max."), vals = listOf("4>4", "3==4", "4<3", "4==4"), correct = 3, check = "true", steps = listOf("Sea L el lado. Los tramos AB, BO, OD, OC, CD y ED miden L. BE pasa por el centro y mide 2L.", "Pedro, ABOD: L + L + L = 3L.", "Luis, ABED: L + 2L + L = 4L.", "Max, ABOCD: L + L + L + L = 4L.", "Luis y Max recorren lo mismo, 4L. La afirmación correcta es la d."), fig = "x25_25", theory = "En un hexágono regular, el centro está a la misma distancia de todos los vértices, y esa distancia es igual al lado. Las diagonales que pasan por el centro miden el doble del lado.", idea = "Todo se mide en lados del hexágono: cada tramo es un lado o una diagonal mayor.", mistake = "Contar BE como un lado L en lugar de 2L. Así Luis tendría 3L y parecería igual a Pedro, alternativa b.", verify = "Pedro recorre menos que los otros dos: 3L < 4L.", letters = "abcd", src = "oficial", year = 2025, num = 25, official = 3))
        l.add(BProb(id = "e25_26", topic = "prob", level = 1, text = "Una maestra realiza una actividad para recordar las propiedades de los números primos y probabilidades. Ella ha traído una bolsa que contiene tarjetas. Cada una de estas tarjetas tiene escrito solo uno de los siguientes números primos:  2, 3, 5, 7, 11, 13, 17, 19.\nLa maestra le pide a Ruth que extraiga, al azar, una tarjeta de la bolsa.\nSegún esta información, ¿cuál es la probabilidad que Ruth extraiga una tarjeta que contenga un número primo?", opts = listOf("§7/8", "§4/8", "1", "0"), vals = listOf("7/8", "4/8", "1", "0"), correct = 2, check = "size(select(n->isprime(n),[2,3,5,7,11,13,17,19]))/8", steps = listOf("Casos posibles: 8 tarjetas.", "Las 8 tienen números primos, así que hay 8 casos favorables.", "Probabilidad: 8/8 = 1. Es un suceso seguro."), theory = "Si todos los casos posibles son favorables, el suceso es seguro y su probabilidad es 1.", idea = "Todas las tarjetas tienen números primos.", mistake = "Pensar que el 2 no es primo por ser par y responder 7/8, alternativa a.", verify = "Ninguno de los números 2, 3, 5, 7, 11, 13, 17 y 19 tiene divisores distintos de 1 y de sí mismo.", trap = "size(select(n->irem(n,2)==1,[2,3,5,7,11,13,17,19]))/8", letters = "abcd", src = "oficial", year = 2025, num = 26, trapOpt = 0, official = 2))
